import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faFile, faPlus } from "@fortawesome/free-solid-svg-icons";
import axios from "axios";

const PlansPurchase = () => {
  const navigate = useNavigate();
  const [success, setSuccessMessage] = useState("");
  const [plans, setPlans] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const handleEdit = (planId) => {
    navigate(`/update-plan/${planId}`);
  };

  const message = localStorage.getItem("success");

  useEffect(() => {
    if (message) {
      setSuccessMessage(message);
      localStorage.removeItem("success");
    }

    const fetchPlans = async () => {
      try {
        const response = await axios.get(
          `${process.env.REACT_APP_API_BASE_URL}/api/get_plans`
        );
        if (response.data.status === 1) {
          setPlans(response.data.data);
        } else {
          setError(response.data.msg);
        }
      } catch (err) {
        setError("Failed to fetch plans.");
      } finally {
        setLoading(false);
      }
    };

    fetchPlans();
  }, []);

  const handleDelete = async (plan_id) => {
    const confirmDelete = window.confirm(
      "Are you sure you want to delete this plan?"
    );
    if (!confirmDelete) return;

    try {
      const response = await fetch(
        `${process.env.REACT_APP_API_BASE_URL}/api/delete_plan`,
        {
          method: "DELETE",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ plan_id }),
        }
      );

      const data = await response.json();
      if (data.status === 1) {
        setPlans((prevPlans) =>
          prevPlans.filter((plan) => plan._id !== plan_id)
        );

        setSuccessMessage("Plan deleted successfully!");
      } else {
        alert("Error while deleting plan: " + data.msg);
      }
    } catch (error) {
      console.error("Error deleting plan:", error);
    }
  };

  return (
    <>
      <div className="w-100 container-fluid mt-24 items-center justify-center">
        {success && <div className="alert alert-success">{success}</div>}
        {loading && <div className="alert alert-secondary">Loading..!</div>}
        {error && <div className="alert alert-danger">{error}</div>}

        <div className="p-2 bg-white border rounded shadow-lg">
          <h4 className="p-2 mb-5 text-center bg-white border rounded shadow-sm h4">
            <FontAwesomeIcon icon={faFile}className="w-8 h-8 mr-4 text-black-500 rounded-full"/>
            Plans
          </h4>

          <div className="mb-3 d-flex justify-content-end">
            <button
              className="btn btn-primary"
              onClick={() => navigate("/add-plan")}
            >
              <FontAwesomeIcon icon={faPlus} /> Add New Plan
            </button>
          </div>

          <div className="row g-4">
            {plans.map((plan, index) => (
              <div className="col-md-4 d-flex justify-content-center" key={index}>
                <div
                  className="card border-secondary"
                  style={{
                    width: "100%", // Full width for the column
                    maxWidth: "350px", // Fixed width for cards
                    height: "500px", // Fixed height for all cards
                    borderRadius: "15px",
                    overflow: "hidden",
                  }}
                >
                  <img
                    src={
                      `${process.env.REACT_APP_API_BASE_URL}` +
                        plan.plan_image || "https://via.placeholder.com/150"
                    }
                    className="card-img-top"
                    alt={plan.plan_name}
                    style={{
                      height: "225px",
                      objectFit: "cover",
                      borderRadius: "15px 15px 0 0",
                    }}
                  />
                  <div className="card-body p-3">

                    {/* Status Badge */}
                    <div className="position-relative">
                      <span
                        className={`badge position-absolute end-0 top-100 mt-2 ${
                          plan.status === "Active" ? "bg-success" : "bg-danger"
                        }`}
                      >
                        {plan.status === "Active" ? "Active" : "Inactive"}
                      </span>
                    </div>


                    <h3 className="card-title h5 text-truncate">
                      {plan.plan_name}
                    </h3>

                    <p className="mb-1 card-text text-truncate">
                      <strong>Features:</strong> {plan.features}
                    </p>
                    <p className="mb-1 card-text">
                      <strong>Price:</strong> &#8377;{plan.plan_price}{" "}
                      <span className="ps-3">
                        <strong>Final Price:</strong> &#8377;{plan.final_price}
                      </span>
                    </p>
                    <p className="mb-1 card-text">
                      <strong>Validity:</strong> {plan.validity}{" "}
                      {plan.validity_unit}
                    </p>
                    <p className="mb-1 card-text">
                      <strong>Offer:</strong> {plan.offer_percentage}%
                    </p>

                    <div className="text-end mt-3">
                      <button
                        onClick={() => handleEdit(plan._id)}
                        className="btn btn-primary"
                      >
                        Edit
                      </button>
                      <button
                        className="btn btn-danger ms-1"
                        onClick={() => handleDelete(plan._id)}
                      >
                        Delete
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
};

export default PlansPurchase;











