import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import Slider from "react-slick";
import { FaRupeeSign, FaEdit, FaTrashAlt } from "react-icons/fa";
import { BsHouseDoorFill } from "react-icons/bs";
import { Ruler } from "lucide-react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faChair, faShareNodes } from "@fortawesome/free-solid-svg-icons";
import { AiOutlineUser } from "react-icons/ai";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const PropertyCard = ({ property, onDelete, onShare, onFavorite }) => {
  const navigate = useNavigate();
  const [activeIndex, setActiveIndex] = useState(0);

  const BASE_URL = process.env.REACT_APP_API_BASE_URL;

  const getValidImageUrl = (img) => {
    if (typeof img !== "string" || !img.trim()) return null;
    return img.startsWith("http") ? img : BASE_URL + img;
  };

  const coverImage = getValidImageUrl(property.cover_image);
  const additionalImages = (property.property_images || [])
    .map((imgObj) => getValidImageUrl(imgObj?.image))
    .filter(Boolean);
  const allImages = [...(coverImage ? [coverImage] : []), ...additionalImages];

  const handleUpdateClick = () => navigate(`/update-property/${property._id}`);
  const handleDeleteClick = () => {
    if (window.confirm("Are you sure you want to delete this property?")) {
      onDelete(property._id);
    }
  };

  const formatPrice = (price) => {
    if (!price || isNaN(price)) return "₹0";
    if (price >= 10000000) return `₹${(price / 10000000).toFixed(1)} Cr`;
    if (price >= 100000) return `₹${(price / 100000).toFixed(1)} L`;
    if (price >= 1000) return `₹${(price / 1000).toFixed(1)} K`;
    return `₹${price}`;
  };

  const convertToSqFt = (area, unit) => {
    if (!area || !unit) return null;
    switch (unit.toLowerCase()) {
      case "sq ft":
        return area;
      case "sq yard":
        return area * 9;
      case "sq mt":
        return area * 10.7639;
      case "acre":
        return area * 43560;
      default:
        return area;
    }
  };

  const sliderSettings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    arrows: false,
    autoplay: true,
    autoplaySpeed: 3000,
    beforeChange: (_, next) => setActiveIndex(next),
    customPaging: (i) => {
      const isActive = i === activeIndex;
      return (
        <div
          style={{
            width: "10px",
            height: "10px",
            borderRadius: "50%",
            background: isActive ? "#fff" : "#888",
            margin: "0 5px",
            cursor: "pointer",
          }}
        />
      );
    },
    appendDots: (dots) => (
      <div
        style={{
          position: "absolute",
          bottom: "10px",
          left: "50%",
          transform: "translateX(-50%)",
          display: "flex",
          justifyContent: "center",
          width: "100%",
        }}
      >
        {dots}
      </div>
    ),
  };

  return (
    <div className="box-border p-4">
      <div className="h-full overflow-hidden shadow rounded-2xl bg-slate-100">
        <div className="w-full overflow-hidden rounded-xl">
          <div className="relative">
            <Link to={`/property-details/${property._id}`} className="block">
              {allImages.length > 1 ? (
                <Slider {...sliderSettings} className="rounded-t-2xl">
                  {allImages.map((imgUrl, idx) => (
                    <div key={idx}>
                      <img
                        src={imgUrl}
                        alt="Property"
                        className="object-cover w-full h-48 rounded-t-2xl"
                        onError={(e) => (e.target.style.display = "none")}
                      />
                    </div>
                  ))}
                </Slider>
              ) : (
                <img
                  src={allImages[0] || "/image/app.png"}
                  alt="Property"
                  className="object-cover w-full h-48 rounded-t-2xl"
                />
              )}
            </Link>

            {/* Days on Houzza */}
            <span className="absolute px-2 py-1 text-xs font-normal text-white rounded-full top-2 left-2 bg-gray-800/60 backdrop-blur-sm">
              {property.days_since_created} days on Houzza


            </span>

            <div className="absolute flex justify-end w-16 gap-1 top-2 right-2">
              <button
                onClick={handleUpdateClick}
                className="text-blue-500 hover:text-blue-700"
              >
                <FaEdit size={20} />
              </button>
              <button
                onClick={handleDeleteClick}
                className="text-red-500 hover:text-red-700"
              >
                <FaTrashAlt size={18} />
              </button>
            </div>



            {/* Virtual Tour & Favorite */}
            <div className="absolute flex items-center space-x-2 top-2 right-2">
              {property.virtual_tour_availability === "Yes" && (
                <span className="flex items-center gap-1 px-2 py-1 text-xs text-white rounded-full bg-gray-800/60 backdrop-blur-sm">
                  Virtual Tour
                </span>
              )}

            </div>

            {/* Buy/Rent & Featured */}
            <div className="absolute bottom-0 left-0">
              <span
                className={`text-white text-xs px-3 py-1 rounded-se-lg ${property.property_category_type === "Buy"
                  ? "bg-green-500"
                  : property.property_category_type === "Rent"
                    ? "bg-blue-500"
                    : "bg-gray-500"
                  }`}
              >
                {property.property_category_type === "Buy"
                  ? "FOR BUY"
                  : property.property_category_type === "Rent"
                    ? "FOR RENT"
                    : "UNKNOWN"}
              </span>
            </div>
            <div className="absolute bottom-0 right-0">
              {property.mark_as_featured === "Yes" && (
                <span className="px-3 py-1 text-xs text-white bg-yellow-500 rounded-ss-lg">
                  FEATURED
                </span>
              )}
            </div>
          </div>

          {/* Info Section */}
          <div className="relative p-4 text-black bg-white">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-semibold truncate">
                {property.property_name}
              </h3>

            </div>

            <p className="text-sm text-gray-500">
              {property.building_type} : {property.property_type}
            </p>

            <div className="flex flex-wrap pt-2 text-sm">
              <div className="flex flex-wrap items-center w-full space-x-6">
                {property.property_category_type === "Rent" && property.rent ? (
                  <p className="flex items-center text-base">
                    <FaRupeeSign className="mr-1 text-blue-600" />
                    {formatPrice(property.rent)}
                    {property.rent_duration && (
                      <span className="ml-1 text-sm text-gray-500">
                        / {property.rent_duration}
                      </span>
                    )}
                  </p>
                ) : property.property_price ? (
                  <p className="flex items-center text-base">
                    <FaRupeeSign className="mr-1 text-purple-600" />
                    {formatPrice(property.property_price)}
                  </p>
                ) : null}

                {property.bhk_type && (
                  <p className="flex items-center text-base">
                    <BsHouseDoorFill className="mr-1 text-purple-600" />
                    {property.bhk_type}
                  </p>
                )}

                {property.area && (
                  <p className="flex items-center text-base">
                    <Ruler size={16} className="mr-1 text-purple-600" />
                    {Math.round(convertToSqFt(property.area, property.area_in))} sq ft
                  </p>
                )}
              </div>

              {property.furnished_type && (
                <div className="flex items-center w-full mt-2">
                  <p className="flex items-center text-base">
                    <FontAwesomeIcon
                      icon={faChair}
                      className="mr-1 text-purple-600"
                    />
                    {property.furnished_type}
                  </p>
                </div>
              )}
            </div>

            <p className="flex items-center gap-2 mt-1 text-sm font-bold text-gray-500 truncate" >
              <img
                src="/image/address_icon.png"
                alt="Location Icon"
                className="object-contain w-4 h-4"
              />
              {property.address_area || "No Address Provided"}
            </p>

            <div className="flex items-center mt-1 mb-0 text-sm truncate">
              {/* <div className="p-2 rounded-full bg-slate-100">
                            <AiOutlineUser className="text-xl text-gray-600" />
                          </div> */}
              <div className="p-2 rounded-full bg-slate-100">
                {property.property_owner_image ? (
                  <img
                    src={`${process.env.REACT_APP_API_BASE_URL}/media/${property.property_owner_image}`}
                    alt="Owner"
                    className="object-cover w-6 h-6 rounded-full"
                  />
                ) : (
                  <AiOutlineUser className="text-xl text-gray-600" size={25} />
                )}
              </div>
              <div className="flex flex-col ml-2">
                <span className="text-sm font-semibold">
                  {property.connect_to_name}
                </span>
                <span>{property.user_type}</span>
              </div>
            </div>


          </div>
        </div>
      </div>
    </div>
  );
};

export default PropertyCard;
