import React, { useState, useContext } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import backgroundImage from "../../assets/images/login.jpg";
import { MyContext } from "../../App";

const LoginForm = () => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const navigate = useNavigate();
  const { setIsAuthenticated } = useContext(MyContext);
  const handleLogin = async (username, password) => {
    // console.log("API Base URL:", process.env.REACT_APP_API_BASE_URL);

     try {
      const response = await axios.post(
        `${process.env.REACT_APP_API_BASE_URL}/api/login/`,
        { username, password }
      );
      sessionStorage.setItem("token", response.data.token);

      // Update the context state to reflect the user is authenticated
      setIsAuthenticated(true);

      setTimeout(() => {
        navigate("/admin");
      }, 100);
    } catch (error) {
      if (error.response) {
        console.error("Login error response:", error.response.data);
        setError(error.response.data.detail || "Invalid username or password");
      } else if (error.request) {
        console.error("Login error request:", error.request);
        setError("No response from server");
      } else {
        console.error("Login error message:", error.message);
        setError("Login failed");
      }
    }
  };
  const handleSubmit = (e) => {
    e.preventDefault();
    handleLogin(username, password);
  };

  return (
    <>
      <div
        className="flex items-center justify-center min-h-screen"
        style={{
          backgroundImage: `url(${backgroundImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
        }}
      >
        <div
          className="w-full max-w-md p-8 rounded-lg"
          style={{
            backgroundColor: "transparent", // Set the background color to transparent
            boxShadow: "0 4px 15px rgba(0, 0, 0, 0.5)", // Add box shadow for the border effect
          }}
        >
          <h2 className="mb-6 text-3xl font-bold text-center text-white">
            Login
          </h2>
          <form onSubmit={handleSubmit}>
            <div className="mb-4">
              <label
                className="block mb-2 text-sm font-bold text-white"
                htmlFor="username"
              >
                Username
              </label>
              <input
                id="username"
                type="text"
                placeholder="Username"
                onChange={(e) => setUsername(e.target.value)}
                required
                className="w-full px-3 py-2 leading-tight text-gray-700 border rounded shadow-md appearance-none focus:outline-none focus:ring-2 focus:ring-blue-400"
              />
            </div>
            <div className="mb-6">
              <label
                className="block mb-2 text-sm font-bold text-white"
                htmlFor="password"
              >
                Password
              </label>
              <input
                id="password"
                type="password"
                placeholder="Password"
                onChange={(e) => setPassword(e.target.value)}
                required
                className="w-full px-3 py-2 mb-3 leading-tight text-gray-700 border rounded shadow-md appearance-none focus:outline-none focus:ring-2 focus:ring-blue-400"
              />
            </div>
            {error && <p className="text-xs italic text-red-500">{error}</p>}{" "}
            {/* Error message */}
            <div className="flex items-center justify-center">
              {" "}
              {/* Center the button container */}
              <button
                type="submit"
                className="px-4 py-2 font-bold text-white bg-blue-500 rounded hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-400"
              >
                Login
              </button>
            </div>
          </form>
        </div>
      </div>
    </>
  );
};

export default LoginForm;
