import { useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import {
  BarChart2, Warehouse, Users, TrendingUp, Bell, Menu, LogOut, User, File, MessageSquare,
  Gift, Clock, Settings, Info, Lock, Shield, HelpCircle,
  Trophy, Video
} from "lucide-react";
import { FaHouseUser, FaUserCircle } from "react-icons/fa";
import axios from 'axios';
import "./style.css";
import houzzaLogo from "./houzza.png";

// Sidebar items configuration
const SIDEBAR_ITEMS = [
  { name: "ADMIN", icon: BarChart2, color: "#6366f1", href: "/admin" },
  { name: "MY INVENTORY", icon: Warehouse, color: "#EC4899", href: "/properties" },
  { name: "PROJECTS", icon: TrendingUp, color: "#F59E0B", href: "/projects" },
  { name: "USERS", icon: Users, color: "#EC4899", href: "/customers" },
  { name: "NOTIFICATIONS", icon: Bell, color: "#10B981", href: "/notificationsList" },
  { name: "PLANS", icon: File, color: "#10B981", href: "/plans-purchase" },
  { name: "INQUIRIES", icon: FaHouseUser, color: "#10B981", href: "/inquiry" },
  { name: "VIRTUAL TOUR", icon: Video, color: "#10B981", href: "/virtual-tour-all" },
  { name: "FEEDBACK", icon: MessageSquare, color: "#F59E0B", href: "/feedbacks" },
  { name: "OFFERS", icon: Gift, color: "#10B981", href: "/offers" },
  { name: "PLAN HISTORY", icon: Clock, color: "#10B981", href: "/plans-purchase-history" },
  { name: "SETTING", icon: Settings, color: "#6EE7B7", href: "/admin-settings" },
  {
    name: "LEGAL",
    icon: Shield,
    color: "#9F7AEA",
    href: null,
    submenu: [
      { name: "ABOUT US", icon: Info, color: "#9F7AEA", href: "/about-us" },
      { name: "PRIVACY", icon: Lock, color: "#9F7AEA", href: "/privacy" },
      { name: "TERMS", icon: Shield, color: "#9F7AEA", href: "/terms" },
      { name: "FAQ", icon: HelpCircle, color: "#9F7AEA", href: "/faq" }
    ]
  }
];

const Sidebar = ({ isSidebarOpen, toggleSidebar }) => {
  const [isLegalsOpen, setIsLegalsOpen] = useState(false);
  const location = useLocation();

  const toggleLegals = () => setIsLegalsOpen((prev) => !prev);
  const isActive = (path) => location.pathname === path;

  return (
    <div
      className={`transition-all duration-500 ease-in-out ${isSidebarOpen ? "w-64" : "w-24"
        } h-full bg-gradient-to-b from-indigo-500 to-indigo-500 z-50 text-white fixed left-0 top-0 rounded-r-lg shadow-lg`}
    >
      <div className="h-full flex flex-col p-4 border-r border-indigo-400">

        {/* Logo */}
        {isSidebarOpen && (
          <div className="absolute left-1/2 top-3 transform -translate-x-1/2">
            <img
              src={houzzaLogo} // Replace with your logo path
              alt="Logo"
              className="w-16 h-16 object-contain"
            />
          </div>
        )}

        <button
          onClick={toggleSidebar}
          className="p-1 rounded-full mb-6 self-end hover:bg-indigo-700 transition-all"
        >
          <Menu size={24} style={{ color: "white" }} />
        </button>

        <div>
          {SIDEBAR_ITEMS.map((item) => (
            <div key={item.href}>
              <Link
                to={item.href}
                onClick={item.name === "LEGAL" ? toggleLegals : undefined}
                className={`no-underline transition-all no-underline hover:no-underline ${isActive(item.href) && !isLegalsOpen // Prevent parent active when submenu is open
                  ? "bg-orange-500 shadow-lg"
                  : ""
                  }`}
                title={!isSidebarOpen ? item.name : ""}
              >
                <div
                  className={`flex items-center p-1 text-sm font-medium rounded-lg ${isActive(item.href) && !isLegalsOpen
                    ? "bg-orange-400 text-white"
                    : "hover:bg-orange-400 text-white"
                    } hover:shadow-md transition-all mb-2`}
                >
                  <item.icon
                    size={20}
                    style={{
                      color: "white",
                      minWidth: "20px",
                    }}
                    className="mr-4"
                  />
                  {isSidebarOpen && <span>{item.name}</span>}
                </div>
              </Link>

              {item.submenu && isLegalsOpen && (
                <div className="bg-indigo-600 rounded-md mt-1 p-1 shadow-lg">
                  {item.submenu.map((submenuItem) => (
                    <Link
                      key={submenuItem.href}
                      to={submenuItem.href}
                      className={`no-underline transition-all no-underline hover:no-underline ${isActive(submenuItem.href)
                        ? "bg-orange-600 shadow-inner"
                        : ""
                        }`}
                      title={!isSidebarOpen ? submenuItem.name : ""}
                    >
                      <div
                        className={`flex items-center p-2 text-sm font-medium rounded-lg no-underline hover:no-underline ${isActive(submenuItem.href)
                          ? "bg-orange-500 text-white"
                          : "hover:bg-orange-500 text-white"
                          } hover:shadow-sm transition-all mb-1`}
                      >
                        <submenuItem.icon
                          size={18}
                          style={{
                            color: "white",
                            minWidth: "18px",
                          }}
                          className={isSidebarOpen ? "mr-4" : "mx-auto"}
                        />
                        {isSidebarOpen && <span>{submenuItem.name}</span>}
                      </div>
                    </Link>
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

const App = () => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const navigate = useNavigate();

  const toggleSidebar = () => setIsSidebarOpen((prev) => !prev);
  const toggleUserMenu = () => setIsUserMenuOpen((prev) => !prev);

  const handleLogout = async () => {
    const token = sessionStorage.getItem("token");
    if (!token) {
      console.error("Token not found");
      navigate("/");
      return;
    }

    try {
      await axios.post(
        `${process.env.REACT_APP_API_BASE_URL}/api/logout/`,
        {},
        {
          headers: {
            Authorization: `Token ${token}`,
          },
        }
      );

      sessionStorage.removeItem("token");

    } catch (error) {
      console.error("Logout error:", error);
    }
  };

  return (
    <div className="flex h-screen">
      <Sidebar isSidebarOpen={isSidebarOpen} toggleSidebar={toggleSidebar} />

      <div
        className={`transition-all duration-300 ease-in-out ${isSidebarOpen ? "ml-64" : "ml-24"
          } flex-grow bg-gray-800 pt-16`}
      >
        {/* Navbar */}

        <nav className="fixed top-0 left-0 right-0 z-40 bg-gradient-to-b from-indigo-500 to-indigo-500 p-4 flex justify-between items-center text-white">
          <button
            onClick={toggleSidebar}
            className="p-3 rounded-full hover:bg-indigo-500 md:hidden"
          >
            <Menu size={24} />
          </button>

          {/* User icon and menu */}
          <div className="ml-auto relative">
            <button
              onClick={toggleUserMenu}
              className="flex items-center justify-center w-10 h-10 rounded-full bg-gray-800 hover:bg-gray-700 "
            >
              <User size={24} />
            </button>
            {isUserMenuOpen && (


              <div className="absolute right-0 mt-2 w-48 bg-white rounded-lg shadow-lg border border-gray-300">
                <ul className="p-2">

                  <li className="px-4 py-2 hover:bg-gray-100 cursor-pointer">
                    <Link to="/profile" className="flex items-center no-underline hover:no-underline text-black">
                      <FaUserCircle size={20} className="mr-2" />
                      Profile
                    </Link>
                  </li>
                  <li className="px-4 py-2 hover:bg-gray-100 cursor-pointer">
                    <Link to="/change-password" className="flex items-center no-underline hover:no-underline text-black">
                      <Lock size={16} className="mr-2" />
                      Change Password
                    </Link>
                  </li>

                  <li className="px-4 py-2 hover:bg-gray-100 cursor-pointer text-black" onClick={handleLogout}>
                    <LogOut size={16} className="mr-2 inline" />
                    Logout
                  </li>
                </ul>
              </div>

            )}


          </div>
        </nav>

        {/* Main content */}
        <div className="pt-16">
          {/* Add your routes and components here */}
        </div>
      </div>
    </div>
  );
};


export default App;
