import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faImage,
  faTag,
  faDollarSign,
  faThList,
  faToggleOn,
  faCalendarAlt,
  faCalendarDay,
  faPercentage,
  faBoxes,
  faCogs,
  faInfoCircle,
  faSave,
  faTimesCircle,
  faPlusCircle,
} from "@fortawesome/free-solid-svg-icons";
import { Link } from "react-router-dom";

const AddPlan = () => {
  const navigate = useNavigate();

  const [plan, setPlan] = useState({
    plan_image: "",
    plan_name: "",
    category_type: "",
    features: "",
    plan_price: "",
    final_price: "",
    validity: "",
    validity_unit: "",
    offer_percentage: "",
    description: "",
    no_of_units: "",
    status: "",
  });

  // Calculate final price whenever plan_price or offer_percentage changes
  useEffect(() => {
    const price = parseFloat(plan.plan_price) || 0;
    const offer = parseFloat(plan.offer_percentage) || 0;
    const calculatedFinalPrice = price - (price * offer) / 100;
    setPlan((prev) => ({
      ...prev,
      final_price: calculatedFinalPrice.toFixed(2),
    }));
  }, [plan.plan_price, plan.offer_percentage]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setPlan({
      ...plan,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Prepare the form data for the request
    const formData = new FormData();
    formData.append("plan_image", plan.plan_image);
    formData.append("plan_name", plan.plan_name);
    formData.append("category_type", plan.category_type);
    formData.append("features", plan.features);
    formData.append("plan_price", String(plan.plan_price));
    formData.append("final_price", String(plan.final_price));
    formData.append("validity", String(plan.validity));
    formData.append("validity_unit", plan.validity_unit);
    formData.append("offer_percentage", String(plan.offer_percentage));
    formData.append("description", plan.description);
    formData.append("no_of_units", String(plan.no_of_units));
    formData.append("status", plan.status);

    // Log FormData contents for debugging
    for (let [key, value] of formData.entries()) {
      console.log(`${key}: ${value}`);
    }

    try {
      const response = await fetch(
        `${process.env.REACT_APP_API_BASE_URL}/api/add_plan`,
        {
          method: "POST",
          body: formData,
        }
      );

      if (response.ok) {
        const data = await response.json();
        console.log("Plan added successfully:", data.msg);
        localStorage.setItem("success", data.msg);
        navigate("/plans-purchase");
      } else {
        const errorData = await response.json();
        console.error("Error while adding plan:", errorData);
        alert(`Failed to add plan: ${errorData.msg || "Unknown error"}`);
      }
    } catch (error) {
      console.error("Error during submission:", error);
      alert("Failed to add the plan. Please try again.");
    }
  };

  return (
    <div className="w-100 container-fluid mt-28">
      {/* Breadcrumb aligned right */}
      <nav className="flex justify-end mb-4" aria-label="Breadcrumb">
        <ol className="flex flex-wrap items-center space-x-2 text-sm md:space-x-4">
          <li>
            <Link
              to="/plans-purchase"
              className="font-medium text-blue-600 transition-colors hover:underline"
            >
              Go TO Plans
            </Link>
          </li>
          <li className="text-gray-400">/</li>
          <li>
            <span className="inline-block px-3 py-1 text-base font-bold text-gray-800 rounded-full">
              Add New Plan Page
            </span>
          </li>
        </ol>
      </nav>

      <form
        onSubmit={handleSubmit}
        className="p-2 bg-white border rounded shadow-lg"
      >
        <div className="text-center">
          <h4 className="p-2 m-2 bg-white border rounded shadow-sm h4">
            <FontAwesomeIcon icon={faPlusCircle} className="mr-2" />
            Add a New Plan
          </h4>
        </div>
        <div className="row">
          <div className="col-md-6">
            <div className="mb-3">
              <label
                htmlFor="plan_image"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faImage} className="mr-2" />
                Plan Image <sup className="text-danger">*</sup>
              </label>
              <input
                type="file"
                className="form-control"
                id="plan_image"
                name="plan_image"
                onChange={(e) =>
                  setPlan({ ...plan, plan_image: e.target.files[0] })
                }
                required
              />
            </div>

            <div className="mb-3">
              <label
                htmlFor="plan_name"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faTag} className="mr-2" />
                Plan Name <sup className="text-danger">*</sup>
              </label>
              <input
                type="text"
                className="form-control"
                id="plan_name"
                name="plan_name"
                value={plan.plan_name}
                onChange={handleChange}
                required
              />
            </div>

            <div className="mb-3">
              <label
                htmlFor="category_type"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faThList} className="mr-2" />
                Plan Category Type <sup className="text-danger">*</sup>
              </label>
              <select
                className="form-select"
                id="category_type"
                name="category_type"
                value={plan.category_type}
                onChange={handleChange}
                required
              >
                <option value="" disabled>
                  Select a category
                </option>
                <option value="Post Properties">Post Properties</option>
                <option value="Contact Details">Contact Details</option>
                <option value="Top Developers">Top Developers</option>
                <option value="Upcoming Projects">Upcoming Projects</option>
                <option value="Featured Properties">Featured Properties</option>
                <option value="Advertising">Advertising</option>
                <option value="Offers">Offers</option>
              </select>
            </div>

            <div className="mb-3">
              <label
                htmlFor="plan_price"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faDollarSign} className="mr-2" />
                Plan Price <sup className="text-danger">*</sup>
              </label>
              <input
                type="number"
                className="form-control"
                id="plan_price"
                name="plan_price"
                value={plan.plan_price}
                onChange={handleChange}
                required
              />
            </div>

            <div className="mb-3">
              <label
                htmlFor="final_price"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faDollarSign} className="mr-2" />
                Final Price <sup className="text-danger">*</sup>
                <span className="ml-2 text-muted">(Auto-calculated)</span>
              </label>
              <input
                type="number"
                className="bg-gray-100 form-control"
                id="final_price"
                name="final_price"
                value={plan.final_price}
                disabled
                required
              />
            </div>

            <div className="mb-3">
              <label htmlFor="status" className="form-label font-weight-bold">
                <FontAwesomeIcon icon={faToggleOn} className="mr-2" />
                Plan Status <sup className="text-danger">*</sup>
              </label>
              <select
                className="form-select"
                id="status"
                name="status"
                value={plan.status}
                onChange={handleChange}
                required
              >
                <option value="" disabled>
                  Select status
                </option>
                <option value="Active">Active</option>
                <option value="Inactive">Inactive</option>
              </select>
            </div>
          </div>

          <div className="col-md-6">
            <div className="mb-3 row">
              <div className="col-md-6">
                <label
                  htmlFor="validity"
                  className="form-label font-weight-bold"
                >
                  <FontAwesomeIcon icon={faCalendarAlt} className="mr-2" />
                  Validity<sup className="text-danger">*</sup>
                </label>
                <input
                  type="number"
                  className="form-control"
                  id="validity"
                  name="validity"
                  value={plan.validity}
                  onChange={handleChange}
                  required
                />
              </div>

              <div className="col-md-6">
                <label
                  htmlFor="validity_unit"
                  className="form-label font-weight-bold"
                >
                  <FontAwesomeIcon icon={faCalendarDay} className="mr-2" />
                  Validity In <sup className="text-danger">*</sup>
                </label>
                <select
                  className="form-select"
                  id="validity_unit"
                  name="validity_unit"
                  value={plan.validity_unit}
                  onChange={handleChange}
                  required
                >
                  <option value="" disabled>
                    Select Unit
                  </option>
                  <option value="Days">Days</option>
                  <option value="Month">Month</option>
                  <option value="Year">Year</option>
                </select>
              </div>
            </div>

            <div className="mb-3">
              <label
                htmlFor="offer_percentage"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faPercentage} className="mr-2" />
                Offer Percentage <sup className="text-danger">*</sup>
              </label>
              <input
                type="number"
                className="form-control"
                id="offer_percentage"
                name="offer_percentage"
                value={plan.offer_percentage}
                onChange={handleChange}
                required
              />
            </div>

            <div className="mb-3">
              <label
                htmlFor="no_of_units"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faBoxes} className="mr-2" />
                Number Of Units <sup className="text-danger">*</sup>
              </label>
              <input
                type="number"
                className="form-control"
                id="no_of_units"
                name="no_of_units"
                value={plan.no_of_units}
                onChange={handleChange}
                required
              />
            </div>

            <div className="mb-3">
              <label htmlFor="features" className="form-label font-weight-bold">
                <FontAwesomeIcon icon={faCogs} className="mr-2" />
                Features <sup className="text-danger">*</sup>
              </label>
              <textarea
                className="form-control"
                id="features"
                name="features"
                value={plan.features}
                onChange={handleChange}
                required
                placeholder="Separate features with a comma (e.g., Unlimited property listings, Priority customer support)"
              ></textarea>
            </div>

            <div className="mb-3">
              <label
                htmlFor="description"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faInfoCircle} className="mr-2" />
                Description <sup className="text-danger">*</sup>
              </label>
              <textarea
                className="form-control"
                id="description"
                name="description"
                value={plan.description}
                onChange={handleChange}
                required
              ></textarea>
            </div>
          </div>
        </div>

        <div className="text-center">
          <button type="submit" className="mt-4 btn btn-primary">
            <FontAwesomeIcon icon={faSave} className="mr-2" />
            Save
          </button>

          <button
            onClick={() => navigate("/plans-purchase")}
            type="button"
            className="mx-2 mt-4 btn btn-secondary"
          >
            <FontAwesomeIcon icon={faTimesCircle} className="mr-2" />
            Cancel
          </button>
        </div>
      </form>
    </div>
  );
};

export default AddPlan;