import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from "react-router-dom";
import axios from 'axios';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faUser, faEnvelope,faHandshake, faPhone, faEye } from '@fortawesome/free-solid-svg-icons';
import $ from "jquery";
import "datatables.net-bs5";
import "bootstrap/dist/css/bootstrap.min.css";

const CategoryUsersList = () => {
  const [items, setItems] = useState([]);
  const navigate = useNavigate(); 
  const [errors, setErrors] = useState("");
  const { user } = useParams();

  useEffect(() => {
    fetchItems();
  }, []);

  const fetchItems = async () => {
    try {
      setErrors('');
      const response = await axios.post(`${process.env.REACT_APP_API_BASE_URL}/api/get_users`, {
        user_type: user, 
      }, {
        headers: {
          "Content-Type": "application/json", 
        },
      });
  
      const result = response;
  
      if (result.data.status === 1 && Array.isArray(result.data.data)) {
        const customersWithDefaultStatus = result.data.data.map((customer) => ({
          ...customer,
          status: customer.status || "Active",
        }));
        setItems(customersWithDefaultStatus);
      } else {
        setErrors("No data available.");
      }
    } catch (error) {
      setErrors("Failed to fetch customers.");
    }
  };

  useEffect(() => {
    if (items.length) {
      $('#userTable').DataTable().destroy();
      $('#userTable').DataTable();
    }
  }, [items]);

  const handleItemClick = (id) => {
    navigate(`/properties/${id}`);
  };

  return (
    <div className="w-100 container-fluid mt-28">
      {errors && <div className="alert alert-danger">{errors}</div>}

      <div className="p-2 bg-white border rounded shadow-lg">
        <div>
          <h4 className="p-2 m-1 text-center bg-white border rounded shadow-sm h4">
          <FontAwesomeIcon icon={faUser} className="text-blue-600" />
            {user} List
          </h4>
        </div>
    
        <div className="table-responsive">
          <table id="userTable" 
            className="table mt-3 table-striped table-bordered"
            style={{ borderCollapse: "collapse", border: "2px solid #B0C4DE" }}
          >
            <thead style={{ backgroundColor: "#0056b3", color: "#fff" }}>
              <tr>
                <th scope="col">
                  <FontAwesomeIcon icon={faUser} /> Profile
                </th>
                <th scope="col">
                  <FontAwesomeIcon icon={faUser} /> Full Name
                </th>
                <th scope="col">
                  <FontAwesomeIcon icon={faEnvelope} /> Email
                </th>
                <th scope="col">
                  <FontAwesomeIcon icon={faPhone} /> Mobile Number
                </th>
                <th scope="col">
                  <FontAwesomeIcon icon={faEye} /> Action
                </th>
              </tr>
            </thead>
            <tbody>
              {items.length ? (
                items.map((item) => (
                  <tr key={item._id}>
                    <td>
                      {item.profile_image ? (
                        <img
                          src={`${process.env.REACT_APP_API_BASE_URL}/${item.profile_image}`}
                          alt={item.full_name || "User"}
                          className="img-thumbnail rounded-circle"
                          style={{ width: "50px", height: "50px", objectFit: "cover" }}
                          onError={(e) => {
                            e.target.style.display = 'none';
                          }}
                        />
                      ) : (
                        <FontAwesomeIcon icon={faUser} className="w-10 h-10 mr-4 text-gray-500 rounded-full" />
                      )}
                    </td>
                    <td>{item.full_name}</td>
                    <td>{item.email}</td>
                    <td>{item.mobile_number}</td>
                    <td>
                      <button
                        className="btn btn-primary btn-sm"
                        onClick={() => handleItemClick(item._id)}
                      >
                        View Properties
                      </button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="5" className="text-center">
                    No {user} available
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default CategoryUsersList;
