import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faPlus, faTrash, faBuilding } from "@fortawesome/free-solid-svg-icons";
import { Link } from "react-router-dom";

const Amenities = () => {
  const [amenities, setAmenities] = useState([]);
  const [errors, setErrors] = useState("");
  const [success, setSuccessMessage] = useState("");
  const navigate = useNavigate();

  const message = localStorage.getItem("success");

  useEffect(() => {
    fetchAmenities();

    if (message) {
      setSuccessMessage(message);
      localStorage.removeItem("success");
    }
  }, []);

  const fetchAmenities = async () => {
    setErrors("");
    setSuccessMessage("");
    try {
      const response = await axios.post(
        `${process.env.REACT_APP_API_BASE_URL}/cust_api/get_amenities`
      );
      setAmenities(response.data.data);
    } catch (error) {
      console.error("Error fetching amenities:", error);
      setErrors("Failed to fetch amenities.");
    }
  };

  const handleDelete = async (property_amenity_id) => {
    const confirmDelete = window.confirm(
      "Are you sure you want to delete this amenity?"
    );
    if (!confirmDelete) return;

    try {
      setErrors("");
      setSuccessMessage("");

      const response = await fetch(
        `${process.env.REACT_APP_API_BASE_URL}/cust_api/remove_property_amenity`,
        {
          method: "DELETE",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ property_amenity_id }),
        }
      );

      const data = await response.json();
      if (data.status === 1) {
        setAmenities((prevAmenities) =>
          prevAmenities.filter((amenity) => amenity._id !== property_amenity_id)
        );
        setSuccessMessage("Amenity deleted successfully!");
      } else {
        alert("Error while deleting amenity: " + data.msg);
      }
    } catch (error) {
      console.error("Error deleting amenity:", error);
    }
  };

  return (
    <div className="w-100 container-fluid mt-28">
      {errors && <div className="alert alert-danger">{errors}</div>}
      {success && <div className="alert alert-success">{success}</div>}

      {/* Breadcrumb aligned right */}
      <nav className="flex justify-end mb-4" aria-label="Breadcrumb">
        <ol className="flex flex-wrap items-center space-x-2 md:space-x-4 text-sm">
          <li>
            <Link
              to="/properties"
              className="text-blue-600 font-medium hover:underline transition-colors"
            >
              Go TO Properties
            </Link>
          </li>

          <li className="text-gray-400">/</li>

          <li>
            <span className="inline-block px-3 py-1 rounded-full text-gray-800 font-bold text-base">
              Property Amenities Page
            </span>
          </li>
        </ol>
      </nav>

      <div className="p-2 bg-white border rounded shadow-lg">
        <div>
          <h4 className="p-2 m-2 text-center bg-white border rounded shadow-sm h4">
            <FontAwesomeIcon icon={faBuilding} className="mr-2" />
            Amenities
          </h4>
        </div>

        <div className="container">
          <button
            onClick={() => navigate("/add-amenity")}
            className="px-4 py-2 mr-2 text-white bg-blue-500 rounded font-bold float-end hover:bg-blue-700 focus:outline-none focus:shadow-outline"
          >
            <FontAwesomeIcon icon={faPlus} /> Add Amenities
          </button>
        </div>

        <div className="container row pt-4">
          {Array.isArray(amenities) && amenities.length > 0 ? (
            amenities.map((amenity, index) => (
              <div key={index} className="col-md-3 mb-4">
                <div className="card border-secondary">
                  <div className="card-body position-relative">
                    {/* Delete icon at top-right */}
                    <button
                      className="btn btn-danger position-absolute top-0 end-0 m-2"
                      onClick={() => handleDelete(amenity._id)}
                    >
                      <FontAwesomeIcon icon={faTrash} />
                    </button>

                    {/* Image and name in a row */}
                    <div className="d-flex align-items-center mb-3">
                      <img
                        src={`${process.env.REACT_APP_API_BASE_URL}${amenity.amenity_icon}`}
                        alt={amenity.amenity_name}
                        className="rounded-circle me-3"
                        style={{
                          width: "60px",
                          height: "60px",
                          objectFit: "cover",
                        }}
                      />
                      <h5
                        className="card-title mt-4"
                        style={{
                          whiteSpace: "nowrap",
                          overflow: "hidden",
                          textOverflow: "ellipsis",
                          maxWidth: "150px", // Adjust based on your card width
                        }}
                      >
                        {amenity.amenity_name}
                      </h5>
                    </div>
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div className="text-center">
              <p>No amenities found.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Amenities;
