import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faSave,faTag,faTimesCircle,faBuilding } from "@fortawesome/free-solid-svg-icons";
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const AddAmenity = () => {

  const navigate = useNavigate();

  const [amenity, setAmenity] = useState({
    user_id: "ADMIN123",
    amenity_icon: "",
    amenity_name: "",
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setAmenity({
      ...amenity,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Prepare the form data for the request
    const formData = new FormData();
    formData.append("user_id", amenity.user_id);
    formData.append("amenity_icon", amenity.amenity_icon);
    formData.append("amenity_name", amenity.amenity_name);


    try {
      // Using fetch
      const response = await fetch(`${process.env.REACT_APP_API_BASE_URL}/cust_api/add_property_amenities`, {
        method: "POST",
        body: formData,
      });

      if (response.ok) {
        const data = await response.json();
        console.log("Amenity added successfully:", data.msg);

        localStorage.setItem('success', 'Amenity added successfully!');
      
        navigate("/amenities");

        // alert("Plan added successfully!");
      } else {
        console.error("Error while adding amenity!");
      }

    } catch (error) {
      console.error("Error during submission:", error);
      alert("Failed to add the amenity. Please try again.");
    }
  };

  return (
    <div className="w-100 container-fluid mt-28">
      <form onSubmit={handleSubmit} className="p-2 bg-white border rounded shadow-lg">
        <div className="text-center">
          <h4 className="p-2 m-2 bg-white border rounded shadow-sm h4">
          <FontAwesomeIcon icon={faBuilding} className="mr-2" />
            Add Amenity</h4>
        </div>
        <div className="row">
          <div className="col-md-6">
            <div className="mb-3">
              <label htmlFor="amenity_icon" className="form-label font-weight-bold">
              <FontAwesomeIcon icon={faBuilding} className="mr-2" />
                Amenity Icon <sup className="text-danger">*</sup>
              </label>
              <input
                type="file"
                className="form-control"
                id="amenity_icon"
                name="amenity_icon"
                onChange={(e) =>
                  setAmenity({ ...amenity, amenity_icon: e.target.files[0] })
                }
                required
              />
            </div>
          </div>

          <div className="col-md-6">
            <div className="mb-3">
              <label htmlFor="amenity_name" className="form-label font-weight-bold">
              <FontAwesomeIcon icon={faTag} className="mr-2" />
                Amenity Name <sup className="text-danger">*</sup>
              </label>
              <input
                type="text"
                className="form-control"
                id="amenity_name"
                name="amenity_name"
                value={amenity.amenity_name}
                onChange={handleChange}
                required
              />
            </div>
          </div>
        </div>

        <div className="text-center">
          <button type="submit" className="mt-4 btn btn-primary">
          <FontAwesomeIcon icon={faSave} className="mr-2" />
            Save
          </button>

          <button onClick={() => navigate("/amenities")}
          type="button" className="mt-4 mx-2 btn btn-secondary">
             <FontAwesomeIcon icon={faTimesCircle} className="mr-2" />
            Cancel
          </button>
        </div>

      </form>
    </div>
  );
};

export default AddAmenity;
