import { useNavigate } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faInfoCircle,
  faIndianRupeeSign,
  faCog,
  faVideo,
} from "@fortawesome/free-solid-svg-icons";
import { Link } from "react-router-dom";

const Settings = () => {
  const navigate = useNavigate();

  const handleClick = (category) => {
    navigate(`/admin-settings/${category}`);
  };

  return (
    <div className="container-fluid mt-28 w-100">
         {/* Breadcrumb aligned right */}
            <nav className="flex justify-end mb-4" aria-label="Breadcrumb">
              <ol className="flex flex-wrap items-center space-x-2 md:space-x-4 text-sm">
                <li>
                  <Link
                    to="/admin"
                    className="text-blue-600 font-medium hover:underline transition-colors"
                  >
                    Home
                  </Link>
                </li>
      
                <li className="text-gray-400">/</li>
      
                <li>
                  <span className="inline-block px-3 py-1 rounded-full text-gray-800 font-bold text-base">
                    Settings Category Page
                  </span>
                </li>
              </ol>
            </nav>
      <div className="p-2 bg-white border rounded shadow-lg">
        <div>
          <h4 className="p-2 text-center color bg-b-600 border rounded shadow-sm h4">
            <FontAwesomeIcon icon={faCog} className="text-xl mr-2" />
            Select A Settings Category
          </h4>
        </div>
        <div className="max-w-6xl mx-auto bg-white rounded-lg shadow-lg grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4 p-4">
          <div
            className="flex flex-col items-center justify-center w-40 h-40 p-4 transition-all cursor-pointer bg-blue-50 hover:bg-blue-300 rounded shadow-lg"
            onClick={() => handleClick("general-setting")}
          >
            <FontAwesomeIcon
              icon={faCog}
              className="text-3xl text-blue-500 mb-2"
            />
            <span className="text-sm font-semibold text-gray-800 text-center">
              General Settings
            </span>
          </div>
          {/* 
          <div
            className="flex flex-col items-center justify-center w-40 h-40 p-4 transition-all cursor-pointer bg-yellow-50 hover:bg-yellow-300 rounded shadow-lg"
            onClick={() => handleClick('descriptions')}
          >
            <FontAwesomeIcon icon={faInfoCircle} className="text-3xl text-yellow-500 mb-2" />
            <span className="text-sm font-semibold text-gray-800 text-center">Description Settings</span>
          </div> */}

          <div
            className="flex flex-col items-center justify-center w-40 h-40 p-4 transition-all cursor-pointer bg-purple-50 hover:bg-purple-300 rounded shadow-lg"
            onClick={() => handleClick("dynamic-price")}
          >
            <FontAwesomeIcon
              icon={faIndianRupeeSign}
              className="text-3xl text-purple-600 mb-2"
            />
            <span className="text-sm font-semibold text-gray-800 text-center">
              Dynamic Pricing Settings
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Settings;
