  import React, { useState, useEffect, useRef } from "react";
  import axios from "axios";
  import { useNavigate } from "react-router-dom";

  // Import jQuery and DataTables
  import $ from "jquery";
  import 'datatables.net-bs5'; // DataTables with Bootstrap 5 styling
  import 'datatables.net-responsive-bs5'; // For responsive DataTables
  import 'datatables.net-bs5/css/dataTables.bootstrap5.min.css'; // DataTables CSS

  // Import FontAwesome Icons
  import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
  import { faUser, faPhoneAlt, faEnvelope, faComment, faClock, faHouseUser } from '@fortawesome/free-solid-svg-icons';

  const InquiriesList = () => {
    const [inquiries, setInquiries] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const navigate = useNavigate();

    // Reference to the table DOM element
    const tableRef = useRef(null);
    // Reference to DataTable instance
    const dataTableRef = useRef(null);

    useEffect(() => {
      const fetchInquiries = async () => {
        try {
          const response = await axios.post(
            `${process.env.REACT_APP_API_BASE_URL}/cust_api/get_property_enquiry`,
            {page:"1",page_size:"10"}
            
          );

          setInquiries(response.data.data); // Access the 'data' key
        } catch (error) {
          if (error.response) {
            setError(`Error: ${error.response.data.msg || 'Something went wrong'}`);
          } else if (error.request) {
            setError("No response from the server. Please try again later.");
          } else {
            setError("An error occurred while setting up the request.");
          }
        } finally {
          setLoading(false);
        }
      };

      fetchInquiries();
    }, []);

    useEffect(() => {
      // Initialize DataTable after inquiries are set
      if (!loading && !error && inquiries.length > 0) {
        if (dataTableRef.current) {
          dataTableRef.current.destroy(); // Destroy existing DataTable instance
        }

        dataTableRef.current = $(tableRef.current).DataTable({
          responsive: true,
          // Add any additional DataTable options here
        });
      }

      // Cleanup function to destroy DataTable on unmount
      return () => {
        if (dataTableRef.current) {
          dataTableRef.current.destroy();
        }
      };
    }, [loading, error, inquiries]);

    const handleViewClick = (property_id) => {
      navigate(`/property-details/${property_id}`);
    };

    return (
      <div className="container-fluid mt-28 w-100">
        {error && <div className="alert alert-danger">{error}</div>} {/* Display error messages */}

        <div className="p-2 bg-white border rounded shadow-lg">
          <h4 className="p-2 m-2 text-center bg-white border rounded shadow-sm h4">
            <FontAwesomeIcon icon={faHouseUser} className="mr-2" /> Inquiries List
          </h4>

          <div>
            <table
              ref={tableRef} // Attach the ref to the table
              id="dataTable"
              className="table table-striped table-bordered"
              style={{ width: "100%", borderCollapse: 'collapse', border: '2px solid #B0C4DE' }}
            >
              <thead style={{ backgroundColor: '#0056b3', color: 'white' }}>
                <tr>
                  <th>#</th>
                  <th><FontAwesomeIcon icon={faUser} className="mr-2" />User Name</th>
                  <th><FontAwesomeIcon icon={faPhoneAlt} className="mr-2" />Contact Number</th>
                  <th><FontAwesomeIcon icon={faEnvelope} className="mr-2" />Email</th>
                  <th><FontAwesomeIcon icon={faComment} className="mr-2" />Message</th>
                  <th><FontAwesomeIcon icon={faClock} className="mr-2" />Timestamp</th>
                  <th><FontAwesomeIcon icon={faHouseUser} className="mr-2" />Inquiry For</th>
                </tr>
              </thead>
              <tbody>
                {inquiries.length > 0 ? (
                  inquiries.map((inquiry, index) => (
                    <tr key={inquiry._id}>
                      <td>{index + 1}</td>
                      <td>{inquiry.name}</td>
                      <td>{inquiry.contact_number}</td>
                      <td>{inquiry.email}</td>
                      <td>{inquiry.message}</td>
                      <td>{inquiry.time_date}</td>
                      <td>
                        <button
                          className="w-full py-2 mt-4 text-white transition-colors bg-blue-600 rounded-md hover:bg-blue-700"
                          onClick={() => handleViewClick(inquiry.property_id)}
                        >
                          <FontAwesomeIcon icon={faHouseUser} className="mr-2" /> Details
                        </button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="7" className="text-center">
                      No inquiries found
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  };

  export default InquiriesList;


