import React from "react";
import { FaEdit, FaTrashAlt,FaRupeeSign } from "react-icons/fa";
import { useNavigate } from "react-router-dom";



const ProjectCard = ({ project, onDelete }) => {
  const navigate = useNavigate();
  const imageUrl = project.cover_image;

  const formatPrice = (price) => {
    if (!price) return "";
    price = parseInt(price);

    if (price >= 10000000) {
      return parseFloat((price / 10000000).toFixed(1)) + " Cr";
    } else if (price >= 100000) {
      return parseFloat((price / 100000).toFixed(1)) + " L";
    } else if (price >= 1000) {
      return parseFloat((price / 1000).toFixed(1)) + " K";
    } else {
      return price.toString();
    }
  };

  const formatAverageProjectPrice = (price) => {
    if (!price) return "";

    // If it's a range (contains "-"), split and format both
    if (typeof price === "string" && price.includes("-")) {
      const parts = price.split("-").map((p) => p.trim());
      return (
        <>
          {parts.map((p, idx) => (
            <span key={idx} className="inline-flex items-center">
              <FaRupeeSign className="inline-block mr-1" />
              {formatPrice(p)}
              {idx === 0 && " - "}
            </span>
          ))}
        </>
      );
    }

    // Normal number formatting
    price = parseInt(price);
    if (isNaN(price)) return "";

    let formatted;
    if (price >= 10000000) {
      formatted = parseFloat((price / 10000000).toFixed(1)) + " Cr";
    } else if (price >= 100000) {
      formatted = parseFloat((price / 100000).toFixed(1)) + " L";
    } else if (price >= 1000) {
      formatted = parseFloat((price / 1000).toFixed(1)) + " K";
    } else {
      formatted = price.toString();
    }
    return (
      <span className="inline-flex items-center">
        <FaRupeeSign className="inline-block mr-1" />
        {formatted}
      </span>
    );
  }

  const handleImageClick = () => {
    if (project._id) {
      navigate(`/project-details/${project._id}`);
    }
  };

  const handleUpdateClick = () => {
    if (project._id) {
      navigate(`/update-project/${project._id}`);
    } else {
      console.error("Property ID is missing.");
    }
  };

  const handleDeleteClick = () => {
    if (project._id) {
      if (window.confirm("Are you sure you want to delete this project?")) {
        onDelete(project._id);
      }
    } else {
      console.error("Something went wrong..!");
    }
  };

  return (
    <div className="max-w-[400px] w-full bg-transparent rounded-3xl ">
      <div className="relative">
        <img
          src={imageUrl}
          alt={project.project_name || "No Project Name Available"}
          className="w-full h-[375px] object-cover rounded-3xl cursor-pointer"
          onClick={handleImageClick}
          onError={(e) => {
            e.target.onerror = null;
            e.target.src = "https://via.placeholder.com/150";
          }}
        />

        {/* Edit and Delete Buttons in Top-Right Corner */}
        <div className="absolute flex space-x-2 top-4 right-4">
          <button
            onClick={handleUpdateClick}
            className="p-2 text-blue-500 bg-white rounded-full shadow-md hover:text-blue-700 hover:shadow-lg"
            aria-label="Update"
          >
            <FaEdit size={20} />
          </button>
          <button
            onClick={handleDeleteClick}
            className="p-2 text-red-500 bg-white rounded-full shadow-md hover:text-red-700 hover:shadow-lg"
            aria-label="Delete"
          >
            <FaTrashAlt size={20} />
          </button>
        </div>

        {/* Logo and Project Name Overlay */}

        <div className="absolute left-1/2 transform -translate-x-1/2 bottom-0 w-[80%] sm:w-80 h-[100px] bg-gray-800/60 backdrop-blur-md flex flex-col justify-end p-4 rounded-t-3xl">
          <div className="absolute -top-7 left-1/2 transform -translate-x-1/2 bg-white border-2 border-gray-200 w-[55px] h-[55px] rounded-full flex justify-center items-center shadow-lg overflow-hidden">
            <img
              src={project.logo}
              alt="Project Logo"
              className="object-cover w-full h-full"
            />
          </div>

          <h3 className="text-center text-white text-lg font-semibold min-h-[24px]">
            {project.project_name || "No Project Name Available"}
          </h3>
        </div>
      </div>

      {/* Description and Price Section */}
      <div className="px-14 sm:px-14">
        <div className="p-3 bg-white shadow-sm rounded-b-3xl">
          <p className="text-[17px] text-gray-500 p-0 m-1 truncate whitespace-nowrap overflow-hidden">
            {project.congfigurations
              ? project.congfigurations.includes("BHK")
                ? project.congfigurations
                : project.congfigurations
                  .split(",")
                  .map((c) => `${c.trim()} BHK`)
                  .join(", ")
              : "No Configurations"}
          </p>

          <p className="p-0 m-1 text-sm text-gray-500">
            {project.project_type}
          </p>
          <p className="flex items-center gap-2 mt-1 text-sm font-bold text-gray-500 truncate">
            <img
              src="/image/address_icon.png"
              alt="Location Icon"
              className="object-contain w-4 h-4"
            />
            {project.address_area || "No Address Provided"}
          </p>

          <div className="flex-1">
            {project.project_properties &&
              project.project_properties.length > 0 && (() => {
                const prices = project.project_properties.map((p) => Number(p.price));
                const minPrice = Math.min(...prices);
                const maxPrice = Math.max(...prices);

                return (
                  <h4 className="flex items-center mb-0 text-xl font-bold text-purple-600 sm:text-2xl">
                    {minPrice === maxPrice ? (
                      formatAverageProjectPrice(minPrice)
                    ) : (
                      <>
                        {formatAverageProjectPrice(minPrice)}
                        <span className="mx-1">-</span>
                        {formatAverageProjectPrice(maxPrice)}
                      </>
                    )}
                  </h4>
                );
              })()}
          </div>


        </div>
      </div>
    </div>
  );
};

export default ProjectCard;