import React, { useEffect, useState, useRef } from "react";
import $ from "jquery";
import "datatables.net-bs5";
import "bootstrap/dist/css/bootstrap.min.css";
import "datatables.net-bs5/css/dataTables.bootstrap5.min.css";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faUserCircle,
  faEnvelope,
  faUserTag,
  faCity,
  faFlag,
  faUser,
  faTrashAlt,
  faUsers,
} from "@fortawesome/free-solid-svg-icons";
import Swal from 'sweetalert2';
import { faUndo } from "@fortawesome/free-solid-svg-icons";

const CustomerList = () => {
  const [customers, setCustomers] = useState([]);
  const [errors, setErrors] = useState("");
  const [success, setSuccess] = useState("");
  const [selectedStatusFilter, setSelectedStatusFilter] = useState("Verified");
  const tableRef = useRef(null);
  const dataTableRef = useRef(null);

  useEffect(() => {
    fetchCustomers(selectedStatusFilter);
  }, [selectedStatusFilter]);

  useEffect(() => {
    // Initialize or reinitialize the DataTable only when offer data is updated
    if (customers.length) {
      // Reinitialize the table after data update
      $("#dataTable").DataTable({
        paging: true,
        searching: true,
        info: true,
        lengthChange: true,
      });
    }
  }, [customers]);

  const fetchCustomers = async (status) => {

    try {
      const response = await fetch(
        `${process.env.REACT_APP_API_BASE_URL}/api/get_users`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            filter_by_status: status === "All" ? null : status,
          }),
        }
      );

      if (!response.ok) throw new Error("Failed to fetch customers.");

      const result = await response.json();

      if (result.status === 1 && Array.isArray(result.data)) {
        $("#dataTable").DataTable().destroy();
        setCustomers(result.data);
      } else {
        setCustomers([]);
      }
    } catch (error) {
      console.error("Error fetching customers:", error);
      setErrors("Failed to fetch customers.");
    }
  };

  const handleStatusChange = async (currentStatus, _id) => {
    const newStatus = currentStatus === "Verified" ? "Block" : "Verified";

    if (
      window.confirm(`Are you sure you want to change status to ${newStatus}?`)
    ) {
      try {
        setSuccess("");
        setErrors("");

        const response = await fetch(
          `${process.env.REACT_APP_API_BASE_URL}/api/update_user_status`,
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({ user_id: _id, status: newStatus }),
          }
        );

        if (!response.ok) throw new Error("Failed to update customer status.");

        // Re-fetch with same filter to reflect updated status
        fetchCustomers(selectedStatusFilter);

        if (newStatus === "Verified") {
          setSuccess("The user has been unblocked successfully.");
        } else {
          setErrors("The user has been blocked successfully.");
        }
      } catch (error) {
        console.error("Error updating customer status:", error);
        setErrors("Failed to update customer status.");
      }
    }
  };

  const handleRestoreUser = async (_id) => {
    const confirm = await Swal.fire({
      title: 'Restore User?',
      text: 'Are you sure you want to restore this user?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Yes, restore!',
      cancelButtonText: 'Cancel'
    });

    if (confirm.isConfirmed) {
      try {
        const response = await fetch(
          `${process.env.REACT_APP_API_BASE_URL}/cust_api/restore_user`,
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({ user_id: _id }),
          }
        );

        const result = await response.json();

        if (result.status === 1) {
          Swal.fire('Restored!', 'User has been restored.', 'success');
          fetchCustomers(selectedStatusFilter);
        } else {
          Swal.fire('Error', result.message || 'Failed to restore user.', 'error');
        }
      } catch (error) {
        console.error("Restore error:", error);
        Swal.fire('Error', 'Something went wrong!', 'error');
      }
    }
  };


  return (
    <div className="w-100 container-fluid mt-28">
      {errors && <div className="alert alert-danger">{errors}</div>}
      {success && <div className="alert alert-success">{success}</div>}

      <div className="p-2 bg-white border rounded shadow-lg">
        <h4 className="p-2 m-2 text-center bg-white border rounded shadow-sm h4">
          <FontAwesomeIcon
            icon={faUsers}
            className="w-8 h-8 mr-4 text-black-500 rounded-full"
          />
          User List
        </h4>

        <div className="d-flex gap-2 mb-3">
          {["All", "Verified", "Unverified", "Blocked"].map((status) => (
            <button
              key={status}
              className={`px-3 py-1.5 rounded ${selectedStatusFilter === status
                  ? "bg-primary text-white"
                  : "bg-light text-dark"
                }`}
              onClick={() => setSelectedStatusFilter(status)}
            >
              {status}
            </button>
          ))}
        </div>

        <table
          id="dataTable"
          className="table mt-3 table-striped table-bordered"
          style={{ borderCollapse: "collapse", border: "2px solid #B0C4DE" }}
        >
          <thead style={{ backgroundColor: "#0056b3", color: "#fff" }}>
            <tr>
              <th>#</th>
              <th>
                <FontAwesomeIcon icon={faUserCircle} className="mr-2" />
                Profile
              </th>
              <th>
                <FontAwesomeIcon icon={faEnvelope} className="mr-2" />
                Contact Details
              </th>
              <th>
                <FontAwesomeIcon icon={faUserTag} className="mr-2" />
                User Type
              </th>
              <th>
                <FontAwesomeIcon icon={faCity} className="mr-2" />
                City
              </th>
              <th>
                <FontAwesomeIcon icon={faFlag} className="mr-2" />
                Status
              </th>
              <th>
                <FontAwesomeIcon icon={faTrashAlt} className="ml-2" />
                Actions
              </th>
            </tr>
          </thead>
          <tbody>
            {
              customers.map((customer, index) => (
                <tr key={customer._id}>
                  <td>{index + 1}</td>
                  <td className="justify-content-center align-items-center">
                    {customer.profile_image ? (
                      <img
                        src={`${process.env.REACT_APP_API_BASE_URL}/${customer.profile_image}`}
                        alt={customer.full_name || "User"}
                        className="object-cover w-12 h-12 mr-4 rounded-full"
                        onError={(e) => {
                          e.target.style.display = "none";
                        }}
                      />
                    ) : (
                      <FontAwesomeIcon
                        icon={faUser}
                        className="w-10 h-10 mr-4 text-gray-500 rounded-full"
                      />
                    )}
                  </td>
                  <td>
                    Name: {customer.full_name} <br />
                    Email: {customer.email || "N/A"} <br />
                    Contact: {customer.mobile_number || "N/A"}
                  </td>
                  <td>{customer.user_type || "N/A"}</td>
                  <td>{customer.city || "N/A"}</td>
                  <td
                    className={
                      customer.status === "Verified"
                        ? "text-success h6 text-center"
                        : "text-danger h6 text-center"
                    }
                  >
                    {customer.status}
                  </td>
                  <td className="text-center">
                    {customer.deleted_at ? (
                      <button
                        className="btn btn-warning btn-sm"
                        title="Restore User"
                        onClick={() => handleRestoreUser(customer._id)}
                      >
                        <FontAwesomeIcon icon={faUndo} /> Restore
                      </button>
                    ) : (
                      <button
                        className={`btn ${customer.status === "Verified" ? "btn-danger" : "btn-success"
                          } btn-sm`}
                        onClick={() =>
                          handleStatusChange(customer.status, customer._id)
                        }
                        title={
                          customer.status === "Verified" ? "Block" : "Unblock"
                        }
                      >
                        {customer.status === "Verified" ? "✘" : "✔"}
                      </button>
                    )}
                  </td>
                </tr>
              ))

            }
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default CustomerList;