import React, { useState, useEffect } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faKey } from "@fortawesome/free-solid-svg-icons";
import { Link } from "react-router-dom";

const DynamicPricing = () => {
  const [keyId, setKeyId] = useState("");
  const [keys, setKeys] = useState("");
  const [error, setError] = useState(null);
  const [successMessage, setSuccessMessage] = useState(null);

  // Fetch existing Dynamic Pricing Keys
  const fetchPricingKeys = () => {
    fetch(`${process.env.REACT_APP_API_BASE_URL}/api/get_dynamic_pricing_keys`)
      .then((response) => response.json())
      .then((data) => {
        // console.log(data);
        if (data.status === 1 && data.data.length > 0) {
          const keyData = data.data[0];
          setKeyId(keyData._id);
          setKeys(keyData.keys);
        }
      })
      .catch((error) => {
        console.error("Error fetching Dynamic Pricing Keys:", error);
        // setError("Failed to fetch pricing keys.");
      });
  };

  useEffect(() => {
    fetchPricingKeys();
  }, []);

  // Handle form submission
  const handleSubmit = (e) => {
    e.preventDefault();

    const payload = {
      keys,
      key_id: keyId,
    };

    fetch(
      `${process.env.REACT_APP_API_BASE_URL}/api/add_dynamic_pricing_keys`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      }
    )
      .then((response) => response.json())
      .then((data) => {
        // console.log(data);
        if (data.status == 1) {
          setSuccessMessage("Keys updated successfully.");
          fetchPricingKeys(); // Refetch the updated content
        } else {
          setError("Failed to update keys.");
        }
      })
      .catch((error) => {
        console.error("Error updating keys:", error);
        setError("Failed to update keys.");
      });
  };

  return (
    <div className="w-100 container-fluid mt-28">
      {error && <div className="alert alert-danger">{error}</div>}
      {successMessage && (
        <div className="alert alert-success">{successMessage}</div>
      )}

      {/* Breadcrumb aligned right */}
      <nav className="flex justify-end mb-4" aria-label="Breadcrumb">
        <ol className="flex flex-wrap items-center space-x-2 md:space-x-4 text-sm">
          <li>
            <Link
              to="/admin-settings"
              className="text-blue-600 font-medium hover:underline transition-colors"
            >
              Go To Admin Setting
            </Link>
          </li>

          <li className="text-gray-400">/</li>

          <li>
            <span className="inline-block px-3 py-1 rounded-full text-gray-800 font-bold text-base">
              Dynamic Pricing Page
            </span>
          </li>
        </ol>
      </nav>

      <form
        onSubmit={handleSubmit}
        className="p-2 bg-white border rounded shadow-lg"
      >
        <div className="row">
          <div className="col-md-12">
            <h4 className="p-2 m-2 text-center bg-white border rounded shadow-sm">
              <FontAwesomeIcon icon={faKey} className="mr-2 text-black" />
              Dynamic Pricing Keys
            </h4>
          </div>
          <div className="col-md-12 p-3">
            <label htmlFor="keys" className="form-label">
              Enter Keys (comma-separated)
            </label>
            <textarea
              id="keys"
              value={keys}
              onChange={(e) => setKeys(e.target.value)}
              className="form-control"
              rows="4"
              placeholder="Enter keys separated by commas"
              required
            />
          </div>
        </div>
        <div className="col-md-12">
          <button type="submit" className="mt-4 btn btn-primary">
            {keyId ? "Update Keys" : "Add Keys"}
          </button>
        </div>
      </form>
    </div>
  );
};

export default DynamicPricing;
