import React, { useEffect, useState } from "react";
import axios from "axios"; // For making API requests
import "bootstrap/dist/css/bootstrap.min.css"; // Bootstrap CSS
import "bootstrap/dist/js/bootstrap.bundle.min"; // Bootstrap JS
import "datatables.net-bs5"; // DataTables with Bootstrap 5 styling
import $ from "jquery"; // jQuery for DataTables
import "datatables.net-bs5"; // DataTables with Bootstrap 5 styling
import "datatables.net-responsive-bs5"; // For responsive DataTables
import "datatables.net-bs5/css/dataTables.bootstrap5.min.css"; // DataTables CSS

// Import FontAwesome Icons
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faCogs,
  faCreditCard,
  faCalendarAlt,
  faUser,
  faBox,
  faCheckCircle,
  faTimesCircle,
  faClock,
} from "@fortawesome/free-solid-svg-icons";

// API Endpoint
const API_URL = `${process.env.REACT_APP_API_BASE_URL}/api/plan_purchase_history`;

const PlansPurchaseHistory = () => {
  // State to store purchase history data
  const [purchaseHistory, setPurchaseHistory] = useState([]);
  const [error, setErrors] = useState(""); // Error handling state

  // Fetch data from API
  useEffect(() => {
    const fetchPurchaseHistory = async () => {
      try {
        const response = await axios.get(API_URL);

        if (response.data.status === 1) {
          const data = response.data.data;
          setPurchaseHistory(data); // Update state with fetched data

          // Initialize DataTables after data is set
          setTimeout(() => {
            $("#purchaseHistoryTable").DataTable({
              responsive: true,
              paging: true,
              lengthChange: true,
              searching: true,
              ordering: true,
              info: true,
              autoWidth: false,
            });
          }, 100); // Give some time for the table to render before initializing DataTables
        } else {
          setErrors("No data available!");
        }
      } catch (error) {
        console.error("Error fetching the purchase history:", error);
        setErrors("Failed to fetch notifications.");
      }
    };

    fetchPurchaseHistory();

    // Clean up DataTable instance on unmount
    return () => {
      $("#purchaseHistoryTable").DataTable().destroy(true);
    };
  }, []);

  return (
    <div className="w-100 container-fluid mt-28">
      {/* Outer Div Styling */}
      {error && <div className="alert alert-danger">{error}</div>}{" "}
      {/* Display error messages */}
      <div className="p-2 bg-white border rounded shadow-lg">
        <h4 className="p-2 m-2 text-center bg-white border rounded shadow-sm h4">
          <FontAwesomeIcon icon={faClock} className="mr-2" />
          Plans Purchase History
        </h4>

        {/* Purchase Plan History Table */}
        <div>
          <table
            id="purchaseHistoryTable"
            className="table mt-3 table-striped table-bordered"
            style={{ borderCollapse: "collapse", border: "2px solid #B0C4DE" }}
          >
            <thead style={{ backgroundColor: "#0056b3", color: "white" }}>
              <tr>
                <th>#</th>
                <th className="px-3 py-2 text-left">
                  <FontAwesomeIcon icon={faBox} className="mr-2" /> Plan Name
                </th>
                <th className="px-3 py-2 text-left">
                  <FontAwesomeIcon icon={faUser} className="mr-2" /> User Name
                </th>
                <th className="px-3 py-2 text-left">
                  <FontAwesomeIcon icon={faCogs} className="mr-2" /> Plan
                  Category Type
                </th>
                <th className="px-3 py-2 text-left">
                  <FontAwesomeIcon icon={faCreditCard} className="mr-2" />{" "}
                  Payment Mode
                </th>
                <th className="px-3 py-2 text-left">
                  <FontAwesomeIcon icon={faCalendarAlt} className="mr-2" />{" "}
                  Purchased On
                </th>
                <th className="px-3 py-2 text-left">
                  <FontAwesomeIcon icon={faCalendarAlt} className="mr-2" />{" "}
                  Expires On
                </th>
                <th className="px-3 py-2 text-left">
                  <FontAwesomeIcon icon={faCheckCircle} className="mr-2" />{" "}
                  Transaction Status
                </th>
                <th className="px-3 py-2 text-left">
                  <FontAwesomeIcon icon={faCheckCircle} className="mr-2" /> Plan
                  Status
                </th>
              </tr>
            </thead>
            <tbody className="text-sm font-light text-secondary">
              {purchaseHistory.map((plan, index) => (
                <tr key={index} className="border-bottom hover:bg-light">
                  <td>{index + 1}</td>
                  <td className="px-3 py-2 text-left">{plan.plan_name}</td>
                  <td className="px-3 py-2 text-left">{plan.user_name}</td>
                  <td className="px-3 py-2 text-left">{plan.category_type}</td>
                  <td className="px-3 py-2 text-left">{plan.payment_mode}</td>
                  <td className="px-3 py-2 text-left">
                    {plan.plan_purchase_date}
                  </td>
                  <td className="px-3 py-2 text-left">
                    {plan.plan_expiry_date}
                  </td>
                  <td className="px-3 py-2 text-left">
                    <FontAwesomeIcon
                      icon={
                        plan.transaction_status === "Success"
                          ? faCheckCircle
                          : faTimesCircle
                      }
                      className={
                        plan.transaction_status === "Success"
                          ? "text-success"
                          : "text-danger"
                      }
                    />
                    {plan.transaction_status}
                  </td>
                  <td className="px-3 py-2 text-left">
                    <FontAwesomeIcon
                      icon={
                        plan.plan_status === "Active"
                          ? faCheckCircle
                          : faTimesCircle
                      }
                      className={
                        plan.plan_status === "Active"
                          ? "text-success"
                          : plan.plan_status === "Pending"
                          ? "text-warning"
                          : "text-danger"
                      }
                    />{" "}
                    {plan.plan_status}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default PlansPurchaseHistory;

