import React, { useState, useEffect } from "react";
import axios from "axios";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";
import { useNavigate } from "react-router-dom";
import Chart from "chart.js/auto";
import { Pie } from "react-chartjs-2";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faUser } from "@fortawesome/free-solid-svg-icons";

const AdminPage = () => {
  // Summary
  const [property_percent, set_property_percent] = useState("");
  const [user_percent, set_user_percent] = useState("");
  const [plan_purchase_percent, set_plan_purchase_percent] = useState("");

  // Properties for
  const [PG, set_PG] = useState(0);
  const [Sell, set_Sell] = useState(0);
  const [Rent, set_Rent] = useState(0);

  // Properties percent
  const [properties_count, set_properties_count] = useState(0);
  const [Approved, set_Approved] = useState(0);
  const [Pending, set_Pending] = useState(0);
  const [Disapproved, set_Disapproved] = useState(0);

  // Recent Properties
  const [recentProperties, setProperties] = useState([]);
  const [recent_properties, set_recent_properties] = useState(0);

  // Recent Projects
  const [recentProjects, setProjects] = useState([]);
  const [recent_projects, set_recent_projects] = useState(0);

  // Revenue
  const [upcomingProjects, setUpcomingProjects] = useState(0);
  const [contactDetails, setContactDetails] = useState(0);
  const [topDevelopers, setTopDevelopers] = useState(0);
  const [offers, setOffers] = useState(0);
  const [postProperties, setPostProperties] = useState(0);
  const [featuredProperties, setFeaturedProperties] = useState(0);

  // Properties added by
  const [owner, setOwner] = useState(0);
  const [developer, setDeveloper] = useState(0);
  const [broker, setBroker] = useState(0);

  // Overview
  const [selectedGraph, setSelectedGraph] = useState("Available");
  const [overviewData, setOverviewData] = useState({ Available: {}, Sold: {} });

  // Activities
  const [activities, setActivities] = useState([]);
  const [activities_count, set_activities_count] = useState(0);

  // Track image errors to prevent repeated logging
  const [imageErrors, setImageErrors] = useState({});

  const navigate = useNavigate();
  const [fromDate, setFromDate] = useState(null);
  const [toDate, setToDate] = useState(null);

  const fetchDashboardData = async (from = null, to = null) => {
    try {
      // Set default dates if not provided (mimic backend logic)
      let fromDate = from;
      let toDate = to;
      if (!fromDate || !toDate) {
        const today = new Date();
        toDate = new Date(today.getFullYear(), today.getMonth(), 0); // Last day of previous month
        fromDate = new Date(toDate.getFullYear(), toDate.getMonth() - 5, 1); // First day of 5 months ago
      }

      const formData = new FormData();
      formData.append("from_date", fromDate.toISOString().split("T")[0]);
      formData.append("to_date", toDate.toISOString().split("T")[0]);

      // Debug: Log the payload
      console.log("Sending payload:", {
        from_date: fromDate.toISOString().split("T")[0],
        to_date: toDate.toISOString().split("T")[0],
      });

      const response = await axios.post(
        `${process.env.REACT_APP_API_BASE_URL}/api/get_dashboard`,
        formData,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );

      const data = response.data.data;
      console.log("API Response:", data); // Debug: Log the response

      // Set summary
      set_property_percent(data.summary.property_percent || 0);
      set_user_percent(data.summary.user_percent || 0);
      set_plan_purchase_percent(data.summary.plan_purchase_percent || 0);

      // Set properties for
      set_Rent(data.properties_for_count.Rent || 0);
      set_Sell(data.properties_for_count.Buy || 0); // Note: Backend uses "Buy", not "Sell"
      set_PG(data.properties_for_count.PG || 0);

      // Set properties percent according to status
      set_properties_count(data.properties_count || 0);
      set_Approved(data.properties_percent.Approved || 0);
      set_Disapproved(data.properties_percent.Disapproved || 0);
      set_Pending(data.properties_percent.Pending || 0);

      // Set count
      set_recent_properties(data.recent_properties || 0);
      set_activities_count(data.activities || 0);
      set_recent_projects(data.recent_projects || 0);

      // Set revenue
      setUpcomingProjects((data.revenue_percent["Upcoming Projects"] || 0).toFixed(2));
      setPostProperties((data.revenue_percent["Post Properties"] || 0).toFixed(2));
      setFeaturedProperties((data.revenue_percent["Featured Properties"] || 0).toFixed(2));
      setTopDevelopers((data.revenue_percent["Top Developers"] || 0).toFixed(2));
      setOffers((data.revenue_percent["Offers"] || 0).toFixed(2));
      setContactDetails((data.revenue_percent["Contact Details"] || 0).toFixed(2));

      // Set properties added by
      setOwner((data.properties_added_by_percent["Owner"] || 0).toFixed(2));
      setBroker((data.properties_added_by_percent["Agent"] || 0).toFixed(2));
      setDeveloper((data.properties_added_by_percent["Builder"] || 0).toFixed(2));

      // Set overview data
      setOverviewData(data.overview_for_percent);
    } catch (error) {
      console.error("Error fetching dashboard data:", error);
    }
  };

  const fetchProperties = async () => {
    try {
      const response = await fetch(
        `${process.env.REACT_APP_API_BASE_URL}/api/recently_posted_properties`
      );
      if (!response.ok) {
        throw new Error("Failed to fetch properties.");
      }

      const result = await response.json();
      if (result.status === 1 && Array.isArray(result.data)) {
        setProperties(result.data);
      } else {
        throw new Error("Invalid data format.");
      }
    } catch (error) {
      console.error("Error fetching properties:", error);
    }
  };

  const fetchProjects = async () => {
    try {
      const response = await fetch(
        `${process.env.REACT_APP_API_BASE_URL}/api/recently_posted_project`
      );
      if (!response.ok) {
        throw new Error("Failed to fetch projects.");
      }

      const result = await response.json();
      if (result.status === 1 && Array.isArray(result.data)) {
        setProjects(result.data);
      } else {
        throw new Error("Invalid data format.");
      }
    } catch (error) {
      console.error("Error fetching projects:", error);
    }
  };

  const fetchActivities = async () => {
    try {
      const response = await axios.get(
        `${process.env.REACT_APP_API_BASE_URL}/api/get_activities`
      );
      if (response.data.status === 1) {
        setActivities(response.data.data);
      } else {
        console.error("Failed to fetch activities");
      }
    } catch (error) {
      console.error("Error fetching activities:", error);
    }
  };

  const truncateText = (text, wordLimit) => {
    if (!text) return "No Name";
    const words = text.split(" ");
    if (words.length > wordLimit) {
      return words.slice(0, wordLimit).join(" ") + "...";
    }
    return text;
  };

  const formatPrice = (price) => {
    if (!price) return "₹0";

    let num = 0;

    if (typeof price === "number") {
      num = price;
    } else if (typeof price === "string") {
      // Handle ranges (e.g., "₹45 K - ₹6 L" or "45000 - 500000")
      const cleanedPrice = price.split("-")[0].trim(); // Take lower bound
      num = parseFloat(cleanedPrice.replace(/[^0-9.]/g, "")) || 0;
    }

    const formatValue = (value, divisor, unit) => {
      let result = value / divisor;
      // Remove .00 if unnecessary
      result = result % 1 === 0 ? result.toFixed(0) : result.toFixed(2);
      return `₹${result} ${unit}`;
    };

    if (num >= 10000000) {
      return formatValue(num, 10000000, "Cr");
    } else if (num >= 100000) {
      return formatValue(num, 100000, "L");
    } else if (num >= 1000) {
      return formatValue(num, 1000, "K");
    }
    return `₹${num}`;
  };


  const handleImageError = (id, type, e) => {
    if (!imageErrors[`${id}-${type}`]) {
      console.warn(`Failed to load ${type} for ${id}: ${e.target.src}`);
      setImageErrors((prev) => ({ ...prev, [`${id}-${type}`]: true }));
      e.target.onerror = null;
      e.target.src = type === "profile" ? "https://placehold.co/32x32" : "https://placehold.co/48x48";
    }
  };

  const getValidImageUrl = (img, type = "cover") => {
    const placeholder = type === "profile" ? "https://placehold.co/32x32" : "https://placehold.co/48x48";
    if (!img || typeof img !== "string" || !img.trim()) {
      console.warn(`Invalid or missing ${type} URL, using placeholder:`, img);
      return placeholder;
    }
    const url = img.startsWith("http") ? img : `${process.env.REACT_APP_API_BASE_URL}${img}`;
    return url;
  };

  useEffect(() => {
    // Set default dates for initial load
    const today = new Date();
    const toDate = new Date(today.getFullYear(), today.getMonth(), 0);
    const fromDate = new Date(toDate.getFullYear(), toDate.getMonth() - 5, 1);
    setFromDate(fromDate);
    setToDate(toDate);
    fetchDashboardData(fromDate, toDate);
    fetchProperties();
    fetchProjects();
    fetchActivities();
  }, []);

  const handleDateChange = (from, to) => {
    setFromDate(from);
    setToDate(to);
    if (from && to) {
      fetchDashboardData(from, to);
    }
  };

  const RevenueData = {
    labels: [
      "Upcoming Projects",
      "Post Properties",
      "Featured Properties",
      "Top Developers",
      "Offers",
      "Contact Details",
    ],
    datasets: [
      {
        data: [
          upcomingProjects || 0,
          postProperties || 0,
          featuredProperties || 0,
          topDevelopers || 0,
          offers || 0,
          contactDetails || 0,
        ],
        backgroundColor: [
          "#ff7f9d",
          "#4682b4",
          "#ffcccb",
          "#ffd700",
          "#e6e6fa",
          "#dda0dd",
        ],
        borderColor: "#ffffff",
        borderWidth: 1,
        hoverOffset: 5,
      },
    ],
  };

  const RevenueOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: "right",
        labels: { font: { size: 14 }, padding: 15 },
      },
      tooltip: {
        callbacks: {
          label: function (context) {
            const label = context.label || "";
            const value = context.raw || 0;
            return `${label}: ${value.toLocaleString()}%`;
          },
        },
      },
    },
  };

  const AddedByData = {
    labels: ["Owner", "Agent", "Builder"],
    datasets: [
      {
        data: [owner || 0, broker || 0, developer || 0],
        backgroundColor: ["#ff7f9d", "#ffd700", "#4682b4"],
        borderColor: "#ffffff",
        borderWidth: 1,
        hoverOffset: 5,
      },
    ],
  };

  const AddedByOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: "right",
        labels: { font: { size: 14 }, padding: 15 },
      },
      tooltip: {
        callbacks: {
          label: function (context) {
            const label = context.label || "";
            const value = context.raw || 0;
            return `${label}: ${value.toLocaleString()}%`;
          },
        },
      },
    },
  };

  const handleViewAll = () => {
    navigate("/recent-properties");
  };

  const handleViewAllProject = () => {
    navigate("/recent-project");
  };

  const handleSubmit = () => {
    navigate("/activities");
  };

  const handleNavigate = () => {
    navigate("/properties-added-by");
  };

  useEffect(() => {
    const data = overviewData[selectedGraph]?.value || [];
    const ctx = document.getElementById("revenueChart")?.getContext("2d");
    if (!ctx) return;

    if (window.revenueChart && typeof window.revenueChart.destroy === "function") {
      window.revenueChart.destroy();
    }

    const chartData = {
      labels: overviewData[selectedGraph]?.title || [],
      datasets: [
        {
          label: `${selectedGraph} Properties`,
          data: data,
          backgroundColor:
            selectedGraph === "Available"
              ? "rgba(54, 162, 235, 0.2)"
              : "rgba(255, 99, 132, 0.2)",
          borderColor:
            selectedGraph === "Available"
              ? "rgba(54, 162, 235, 1)"
              : "rgba(255, 99, 132, 1)",
          borderWidth: 1,
        },
      ],
    };

    window.revenueChart = new Chart(ctx, {
      type: "bar",
      data: chartData,
      options: {
        scales: {
          y: { beginAtZero: true },
        },
      },
    });

    return () => {
      if (window.revenueChart) {
        window.revenueChart.destroy();
      }
    };
  }, [overviewData, selectedGraph]);

  return (
    <div className="container max-w-6xl mt-28">
      <div className="p-2 mx-2 mb-2 border rounded d-flex justify-content-end">
        <div className="mr-8 d-flex flex-column align-items-end">
          <div className="d-flex justify-content-end w-100">
            <label className="mb-0 mr-2 font-weight-bold">From:</label>
            <DatePicker
              selected={fromDate}
              onChange={(date) => handleDateChange(date, toDate)}
              selectsStart
              startDate={fromDate}
              endDate={toDate}
              dateFormat="yyyy-MM-dd"
              className="border rounded form-control"
              placeholderText="Select date"
            />
          </div>
        </div>
        <div className="d-flex flex-column align-items-end">
          <div className="d-flex justify-content-end w-100">
            <label className="mb-0 mr-2 font-weight-bold">To:</label>
            <DatePicker
              selected={toDate}
              onChange={(date) => handleDateChange(fromDate, date)}
              selectsEnd
              startDate={fromDate}
              endDate={toDate}
              minDate={fromDate}
              dateFormat="yyyy-MM-dd"
              className="border rounded form-control"
              placeholderText="Select date"
            />
          </div>
        </div>
      </div>

      <div className="justify-around row">
        <div className="col-md-6">
          <div
            className="relative w-full p-5 text-black bg-white rounded shadow"
            style={{ height: "340px" }}
          >
            <h3 className="px-2 font-bold text-black">Revenue Distribution</h3>
            <Pie data={RevenueData} options={RevenueOptions} />
          </div>
        </div>
        <div className="col-md-6">
          <div
            className="relative w-full p-5 text-black bg-white rounded shadow"
            onClick={handleNavigate}
            style={{ height: "340px", cursor: "pointer" }}
          >
            <h3 className="px-2 font-bold text-black">Properties Added By</h3>
            <Pie data={AddedByData} options={AddedByOptions} />
          </div>
        </div>
      </div>

      <div className="pt-4 row">
        <div className="col-md-4 col-12">
          <div
            className="p-4 text-black bg-white rounded shadow position-relative"
            style={{ height: "150px" }}
          >
            <h3 className="py-2 font-bold text-black">For Buy</h3>
            <svg
              className="position-absolute start-0 w-100"
              style={{ height: "80px", bottom: "6px" }}
              viewBox="0 0 100 50"
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
            >
              <defs>
                <linearGradient id="blue-gradient" x1="0%" y1="0%" x2="0%" y2="100%">
                  <stop offset="0%" style={{ stopColor: "#add8e6", stopOpacity: 1 }} />
                  <stop offset="100%" style={{ stopColor: "#f0f8ff", stopOpacity: 1 }} />
                </linearGradient>
              </defs>
              <path
                d="M0 30 C10 10, 30 20, 40 30 C50 40, 70 20, 80 30 C90 40, 100 20, 100 30 V50 H0 Z"
                fill="url(#blue-gradient)"
                stroke="transparent"
                strokeWidth="2"
              />
              <path
                d="M0 30 C10 10, 30 20, 40 30 C50 40, 70 20, 80 30 C90 40, 100 20, 100 30"
                fill="none"
                stroke="#87ceeb"
                strokeWidth="2"
              />
            </svg>
            <div className="z-10 position-relative">
              <p>{`${Sell.toFixed(2)}%`}</p>
            </div>
          </div>
        </div>
        <div className="col-md-4 col-12">
          <div
            className="p-4 text-black bg-white rounded shadow position-relative"
            style={{ height: "150px" }}
          >
            <h3 className="py-2 font-bold text-black">For Rent</h3>
            <svg
              className="position-absolute start-0 w-100"
              style={{ height: "80px", bottom: "6px" }}
              viewBox="0 0 100 50"
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
            >
              <defs>
                <linearGradient id="green-gradient" x1="0%" y1="0%" x2="0%" y2="100%">
                  <stop offset="0%" style={{ stopColor: "#90ee90", stopOpacity: 1 }} />
                  <stop offset="100%" style={{ stopColor: "#f0fff0", stopOpacity: 1 }} />
                </linearGradient>
              </defs>
              <path
                d="M0 30 C10 10, 30 20, 40 30 C50 40, 70 20, 80 30 C90 40, 100 20, 100 30 V50 H0 Z"
                fill="url(#green-gradient)"
                stroke="transparent"
                strokeWidth="2"
              />
              <path
                d="M0 30 C10 10, 30 20, 40 30 C50 40, 70 20, 80 30 C90 40, 100 20, 100 30"
                fill="none"
                stroke="#32cd32"
                strokeWidth="2"
              />
            </svg>
            <div className="z-10 position-relative">
              <p>{`${Rent.toFixed(2)}%`}</p>
            </div>
          </div>
        </div>
        <div className="col-md-4 col-12">
          <div
            className="p-4 text-black bg-white rounded shadow position-relative"
            style={{ height: "150px" }}
          >
            <h3 className="py-2 font-bold text-black">For PG</h3>
            <svg
              className="position-absolute start-0 w-100"
              style={{ height: "80px", bottom: "6px" }}
              viewBox="0 0 100 50"
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
            >
              <defs>
                <linearGradient id="purple-gradient" x1="0%" y1="0%" x2="0%" y2="100%">
                  <stop offset="0%" style={{ stopColor: "#dda0dd", stopOpacity: 1 }} />
                  <stop offset="100%" style={{ stopColor: "#f8f0ff", stopOpacity: 1 }} />
                </linearGradient>
              </defs>
              <path
                d="M0 30 C10 10, 30 20, 40 30 C50 40, 70 20, 80 30 C90 40, 100 20, 100 30 V50 H0 Z"
                fill="url(#purple-gradient)"
                stroke="transparent"
                strokeWidth="2"
              />
              <path
                d="M0 30 C10 10, 30 20, 40 30 C50 40, 70 20, 80 30 C90 40, 100 20, 100 30"
                fill="none"
                stroke="#9370db"
                strokeWidth="2"
              />
            </svg>
            <div className="z-10 position-relative">
              <p>{`${PG.toFixed(2)}%`}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="pt-4 row">
        <div className="mb-4 col-md-4 col-12">
          <div
            className="p-4 text-black bg-white rounded-lg shadow-lg d-flex flex-column h-100"
            style={{ minHeight: "350px" }}
          >
            <p className="mb-4 text-lg font-bold text-black">Properties Availability</p>
            <div className="flex-wrap gap-2 mb-3 d-flex align-items-end justify-content-center justify-content-md-start">
              <button
                className={`px-3 py-1.5 rounded ${selectedGraph === "Available" ? "bg-primary text-white" : "bg-light text-dark"
                  }`}
                onClick={() => setSelectedGraph("Available")}
              >
                Available
              </button>
              <button
                className={`px-3 py-1.5 rounded ${selectedGraph === "Sold" ? "bg-primary text-white" : "bg-light text-dark"
                  }`}
                onClick={() => setSelectedGraph("Sold")}
              >
                Sold
              </button>
            </div>
            <div className="flex-grow-1 position-relative w-100">
              <div className="top-0 position-absolute start-0 w-100 h-100">
                <canvas id="revenueChart" style={{ width: "100%", height: "100%" }}></canvas>
              </div>
            </div>
          </div>
        </div>
        <div className="mb-4 col-md-4 col-12">
          <div
            className="justify-between p-4 text-black bg-white rounded-lg shadow-lg d-flex flex-column h-100"
            style={{ minHeight: "350px" }}
          >
            <h3 className="mb-2 text-xl font-bold text-dark">Summary</h3>
            <div className="justify-center gap-4 d-flex flex-column flex-grow-1">
              <div className="mb-4">
                <div className="flex-wrap d-flex justify-content-between align-items-center">
                  <p className="mb-1 text-lg">Properties:</p>
                  <span className="mb-1 text-sm text-danger fw-bold">{`${property_percent}%`}</span>
                </div>
                <div className="w-100 bg-light rounded-pill" style={{ height: "25px" }}>
                  <div
                    className="bg-danger rounded-pill"
                    style={{ width: `${property_percent}%`, height: "100%" }}
                  ></div>
                </div>
              </div>
              <div className="mb-4">
                <div className="flex-wrap d-flex justify-content-between align-items-center">
                  <p className="mb-1 text-lg">Users:</p>
                  <span className="mb-1 text-sm text-primary fw-bold">{`${user_percent}%`}</span>
                </div>
                <div className="w-100 bg-light rounded-pill" style={{ height: "25px" }}>
                  <div
                    className="bg-primary rounded-pill"
                    style={{ width: `${user_percent}%`, height: "100%" }}
                  ></div>
                </div>
              </div>
              <div className="mb-4">
                <div className="flex-wrap d-flex justify-content-between align-items-center">
                  <p className="mb-1 text-lg">Plans Purchase:</p>
                  <span className="mb-1 text-sm text-success fw-bold">{`${plan_purchase_percent}%`}</span>
                </div>
                <div className="w-100 bg-light rounded-pill" style={{ height: "25px" }}>
                  <div
                    className="bg-success rounded-pill"
                    style={{ width: `${plan_purchase_percent}%`, height: "100%" }}
                  ></div>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div className="mb-4 col-md-4 col-12">
          <div
            className="justify-between p-4 text-black bg-white rounded-lg shadow-lg d-flex flex-column h-100"
            style={{ minHeight: "350px" }}
          >
            <h3 className="mb-2 text-xl font-bold text-dark">
              Recent Properties {`(${recent_properties})`}
            </h3>
            <ul className="overflow-auto list-unstyled flex-grow-1 w-100">
              {recentProperties.slice(0, 3).map((property, idx) => (
                <li className="my-3 d-flex align-items-center" key={property._id || idx}>
                  <img
                    src={getValidImageUrl(property.cover_image, "cover")}
                    alt={property.property_name || "No Property Name"}
                    className="rounded me-3"
                    style={{ width: "48px", height: "48px" }}
                    onError={(e) => handleImageError(property._id || idx, "cover", e)}
                  />
                  <div>
                    <h5 className="mb-1 text-sm fw-semibold text-dark">
                      {truncateText(property.property_name, 2)}
                    </h5>
                    <p className="mb-0 text-sm text-muted">
                      {formatPrice(property.property_price)}
                    </p>
                  </div>
                </li>
              ))}
            </ul>
            <div className="flex justify-center mt-auto">
              <button
                onClick={handleViewAll}
                className="px-4 py-2 text-white transition-all duration-300 rounded-md shadow-md bg-gradient-to-r from-blue-500 to-blue-700 hover:from-blue-600 hover:to-blue-800"
              >
                View All
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="pt-4 row">
        {/* Recent Projects Box */}
        <div className="mb-4 col-md-4 col-12">
          <div
            className="justify-between p-4 text-black bg-white rounded-lg shadow-lg d-flex flex-column h-100"
            style={{ minHeight: "350px" }}
          >
            <h3 className="mb-2 text-xl font-bold text-dark">
              Recent Projects {`(${recent_projects})`}
            </h3>
            <ul className="overflow-auto list-unstyled flex-grow-1 w-100">
              {recentProjects.slice(0, 3).map((project, idx) => (
                <li className="my-3 d-flex align-items-center" key={project._id || idx}>
                  <img
                    src={getValidImageUrl(project.cover_image, "cover")}
                    alt={project.project_name || "No Project Name"}
                    className="rounded me-3"
                    style={{ width: "48px", height: "48px" }}
                    onError={(e) => handleImageError(project._id || idx, "cover", e)}
                  />
                  <div>
                    <h5 className="mb-1 text-sm fw-semibold text-dark">
                      {truncateText(project.project_name, 2)}
                    </h5>
                    <p className="mb-0 text-sm text-muted">
                      {formatPrice(project.average_project_price)}
                    </p>
                  </div>
                </li>
              ))}
            </ul>
            <div className="flex justify-center mt-auto">
              <button
                onClick={handleViewAllProject}
                className="px-4 py-2 text-white transition-all duration-300 rounded-md shadow-md bg-gradient-to-r from-blue-500 to-blue-700 hover:from-blue-600 hover:to-blue-800"
              >
                View All
              </button>
            </div>
          </div>
        </div>

        {/* Properties Approval Status Box */}
        <div className="mb-4 col-md-4 col-12">
          <div className="flex flex-col p-4 py-6 bg-white rounded-lg shadow-md h-100" style={{ minHeight: "350px" }}>
            <h2 className="mb-4 text-xl font-bold">
              Properties Approval Status: <span className="text-lg font-bold">({`${properties_count}`})</span>
            </h2>
            <div className="flex flex-col gap-4 lg:flex-row">
              <div className="flex flex-col w-full p-6 rounded-lg">
                <h3 className="mb-1 text-lg font-bold">Approved</h3>
                <svg className="w-full" height="30" viewBox="0 0 100 30">
                  <path
                    d="M0 20 C10 5, 30 25, 50 20 C70 15, 90 25, 100 20"
                    fill="none"
                    stroke="#a855f7"
                    strokeWidth="2"
                  />
                </svg>
                <p className="mt-1 text-lg font-bold" style={{ color: "#a855f7" }}>
                  {`${Approved.toFixed(2)}%`}
                </p>
              </div>
              <div className="flex flex-col w-full p-6 rounded-lg">
                <h3 className="mb-1 text-lg font-bold">Disapproved</h3>
                <svg className="w-full" height="30" viewBox="0 0 100 30">
                  <path
                    d="M0 20 C10 5, 30 25, 50 20 C70 15, 90 25, 100 20"
                    fill="none"
                    stroke="#f87171"
                    strokeWidth="2"
                  />
                </svg>
                <p className="mt-1 text-lg font-bold" style={{ color: "#f87171" }}>
                  {`${Disapproved.toFixed(2)}%`}
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Activities Box */}
        <div className="mb-4 col-md-4 col-12">
          <div
            className="p-4 text-black bg-white rounded-lg shadow-lg d-flex flex-column h-100"
            style={{ minHeight: "350px" }}
          >
            <h3 className="mb-3 text-xl font-bold text-gray-800">
              Activities {`(${activities_count})`}
            </h3>
            <ul className="flex-grow mb-4 space-y-2 overflow-auto">
              {activities.slice(0, 3).map((activity, index) => (
                <li
                  key={activity._id || index}
                  className="flex items-center pb-3 text-sm text-gray-700 border-b border-blue-100"
                >
                  {activity.user_profile ? (
                    <img
                      src={getValidImageUrl(`/media/${activity.user_profile}`, "profile")}
                      alt={activity.username || "User Photo"}
                      className="object-cover w-8 h-8 mr-4 rounded-full"
                      onError={(e) => handleImageError(activity._id || index, "profile", e)}
                    />
                  ) : (
                    <FontAwesomeIcon
                      icon={faUser}
                      className="w-5 h-5 mr-4 text-gray-500"
                    />
                  )}
                  <span className="leading-tight">
                    {activity.sentance}: {activity.username}
                  </span>
                </li>
              ))}
            </ul>
            <div className="flex justify-center mt-auto">
              <button
                onClick={handleSubmit}
                className="px-3 py-2 text-white transition-all duration-300 rounded-md shadow-md bg-gradient-to-r from-blue-500 to-blue-700 hover:from-blue-600 hover:to-blue-800"
              >
                View All
              </button>
            </div>
          </div>
        </div>
      </div>


    </div>
  );
};

export default AdminPage;