import React, { useEffect, useState } from "react";
import axios from "axios";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faPlus,
  faBell,
  faCommentDots,
  faUsers,
  faClock,
  faUser,
  faPen,
} from "@fortawesome/free-solid-svg-icons";
import "bootstrap/dist/css/bootstrap.min.css";
import $ from "jquery"; // jQuery for DataTables
import "datatables.net-bs5"; // DataTables with Bootstrap 5 styling
import "datatables.net-responsive-bs5"; // For responsive DataTables
import "datatables.net-bs5/css/dataTables.bootstrap5.min.css"; // DataTables CSS
import { useNavigate } from "react-router-dom";

const NotificationList = () => {
  const [notifications, setNotifications] = useState([]);
  const [error, setErrors] = useState(""); // Error handling state
  const [success, setSuccessMessage] = useState("");
  const navigate = useNavigate();

  const message = localStorage.getItem("success");

  useEffect(() => {
    if (message) {
      setSuccessMessage(message);
      localStorage.removeItem("success");
    }

    const fetchNotifications = async () => {
      try {
        const response = await axios.get(
          `${process.env.REACT_APP_API_BASE_URL}/api/get_notifications`
        );
        // console.log(response.data);
        setNotifications(response.data.data);
      } catch (error) {
        // console.error('Error fetching notifications:', error);
        setErrors("Failed to fetch notifications.");
      }
    };

    fetchNotifications();
  }, []);

  // Initialize DataTable after fetching notifications
  useEffect(() => {
    if (notifications && notifications.length) {
      // Initialize DataTable
      $("#dataTable").DataTable({
        paging: true,
        searching: true,
        responsive: true,
        destroy: true, // Ensure table is destroyed when re-rendering
      });

      // Cleanup: destroy DataTable on component unmount or when notifications change
      return () => {
        if ($.fn.DataTable.isDataTable("#dataTable")) {
          $("#dataTable").DataTable().destroy(true);
        }
      };
    }
  }, [notifications]);

  // Example helper to format a date string nicely
  const formatDate = (dateString) => {
    if (!dateString) return "";

    const options = {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    };

    return new Date(dateString).toLocaleString("en-IN", options);
  };

  return (
    <div className="container fluid w-100 mt-28">
      {error && <div className="alert alert-danger">{error}</div>}{" "}
      {/* Display error messages */}
      {success && <div className="alert alert-success">{success}</div>}{" "}
      {/* Display success messages */}
      <div className="p-2 bg-white border rounded shadow-lg">
        <h4 className="p-2 m-2 text-center bg-white border rounded shadow-sm h4">
          <FontAwesomeIcon icon={faBell} />
          Notifications
        </h4>

        <div className="mb-3 d-flex justify-content-end">
          <button
            className="btn btn-primary"
            onClick={() => navigate("/notification")}
          >
            <FontAwesomeIcon icon={faPlus} /> Add Notification
          </button>
        </div>

        <div>
          <table
            id="dataTable"
            className="table table-striped table-bordered"
            style={{ borderCollapse: "collapse", border: "2px solid #B0C4DE" }}
          >
            <thead style={{ backgroundColor: "#0056b3", color: "#fff" }}>
              <tr>
                <th> #</th>
                <th>
                  <FontAwesomeIcon icon={faPen} className="mr-2" /> Title
                </th>
                <th>
                  <FontAwesomeIcon icon={faCommentDots} className="mr-2" />{" "}
                  Message
                </th>
                <th>
                  <FontAwesomeIcon icon={faUsers} className="mr-2" /> Sent To
                </th>
                <th>
                  <FontAwesomeIcon icon={faClock} className="mr-2" /> Timestamp
                </th>
              </tr>
            </thead>
            <tbody>
              {notifications && notifications.length > 0 ? (
                notifications.map((notification, index) => (
                  <tr key={notification._id}>
                    <td style={{ paddingTop: "20px", paddingBottom: "25px" }}>
                      {index + 1}
                    </td>
                    <td style={{ paddingTop: "20px", paddingBottom: "25px" }}>
                      {notification.notification_title}
                    </td>
                    <td style={{ paddingTop: "20px", paddingBottom: "25px" }}>
                      {notification.message}
                    </td>
                    <td style={{ paddingTop: "20px", paddingBottom: "25px" }}>
                      {notification.send_to
                        .split("|")
                        .map(
                          (word) => word.charAt(0).toUpperCase() + word.slice(1)
                        )
                        .join(", ")}
                    </td>
                    <td style={{ paddingTop: "20px", paddingBottom: "20px" }}>
                      {notification.timestamp
                        ? formatDate(notification.timestamp)
                        : "—"}
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="5" className="text-center">
                    No notifications found
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default NotificationList;
