import React, { useState, useEffect, useRef } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faBell } from "@fortawesome/free-solid-svg-icons";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "datatables.net-bs5";
import $ from "jquery";
import "datatables.net-bs5/css/dataTables.bootstrap5.min.css";

const MySchedules = () => {
  const [mySchedules, setMySchedules] = useState([]);
  const [error, setError] = useState("");
  const [pagination, setPagination] = useState({
    current_page: 1,
    total_pages: 1,
    total_count: 0,
    page_size: 10,
  });
  const myTableRef = useRef(null);
  const myDataTableInstance = useRef(null);
  const userId = "67f0ff69d7908f15767d3e64";
  const navigate = useNavigate();

  // Truncate long text to prevent table overflow
  const truncateText = (text, maxLength = 50) => {
    if (!text) return "N/A";
    return text.length > maxLength ? text.substring(0, maxLength) + "..." : text;
  };

  // Fetch schedules from API
  const fetchSchedules = async (page = 1, pageSize = pagination.page_size) => {
    try {
      const response = await axios.post(
        `${process.env.REACT_APP_API_BASE_URL}/cust_api/get_virtual_tour_schedule`,
        { user_id: userId, page: page.toString(), page_size: pageSize.toString() }
      );
      setMySchedules(response.data.data);
      setPagination({
        current_page: Number(response.data.current_page) || 1,
        total_pages: Number(response.data.total_pages) || 1,
        total_count: Number(response.data.total_count) || 0,
        page_size: Number(response.data.page_size) || pageSize,
      });
      setError("");
    } catch (error) {
      setMySchedules([]);
      setError("No virtual tours scheduled yet!");
    }
  };

  useEffect(() => {
    fetchSchedules(pagination.current_page);

    return () => {
      // Cleanup DataTable instance
      if (myDataTableInstance.current) {
        myDataTableInstance.current.destroy();
        $(myTableRef.current).empty();
      }
    };
  }, []);

  const handleTabChange = (tab) => {
    navigate(tab === "all" ? "/virtual-tour-all" : "/virtual-tour-my");
  };

  // Initialize DataTable when schedules or pagination change
  useEffect(() => {
    if (myDataTableInstance.current) {
      myDataTableInstance.current.destroy();
      $(myTableRef.current).empty();
    }

    if (mySchedules && mySchedules.length > 0) {
      myDataTableInstance.current = $(myTableRef.current).DataTable({
        paging: true,
        searching: true,
        responsive: false, // Disable responsive to prevent extra control column
        serverSide: true,
        processing: true,
        pageLength: pagination.page_size,
        lengthMenu: [10, 25, 50],
        ajax: {
          url: `${process.env.REACT_APP_API_BASE_URL}/cust_api/get_virtual_tour_schedule`,
          type: "POST",
          data: function (d) {
            return {
              user_id: userId,
              page: Math.ceil((d.start + 1) / d.length).toString(),
              page_size: d.length.toString(),
            };
          },
          dataSrc: function (json) {
            setPagination({
              current_page: Number(json.current_page) || 1,
              total_pages: Number(json.total_pages) || 1,
              total_count: Number(json.total_count) || 0,
              page_size: Number(json.page_size) || pagination.page_size,
            });
            return json.data || [];
          },
          dataFilter: function (data) {
            const json = JSON.parse(data);
            return JSON.stringify({
              recordsTotal: Number(json.total_count) || 0,
              recordsFiltered: Number(json.total_count) || 0,
              data: json.data || [],
            });
          },
        },
        columns: [
          {
            data: null,
            title: "#",
            render: (data, type, row, meta) => meta.row + 1,
            width: "5%",
          },
          {
            data: "user_details",
            title: "Schedule By",
            render: (data) =>
              `<div>${truncateText(data?.full_name)}</div>
               <div>${truncateText(data?.email)}</div>
               <div>${truncateText(data?.mobile_number)}</div>`,
            width: "25%",
          },
          {
            data: "property_owner_details",
            title: "Schedule With",
            render: (data) =>
              `<div>${truncateText(data?.full_name)}</div>
               <div>${truncateText(data?.email)}</div>
               <div>${truncateText(data?.mobile_number)}</div>`,
            width: "25%",
          },
          {
            data: null,
            title: "Property Details",
            render: (data) =>
              data.tour_type === "Property" && data.property_details
                ? `<div>${truncateText(data.property_details?.property_name)}</div>
                   <div>${truncateText(data.property_details?.address, 30)}</div>
                   <div>${truncateText(data.property_details?.city_name)}</div>`
                : data.tour_type === "Project" && data.project_details
                ? `<div>${truncateText(data.project_details?.project_name)}</div>
                   <div>${truncateText(data.project_details?.address, 30)}</div>
                   <div>${truncateText(data.project_details?.city_name)}</div>`
                : "N/A",
            width: "35%",
          },
          {
            data: null,
            title: "Time",
            render: (data) =>
              `${truncateText(data.timeslot)} ${data.time_unit || ""}<br/>${truncateText(data.schedule_date)}`,
            width: "15%",
          },
        ],
        columnDefs: [
          {
            targets: "_all",
            render: function (data, type, row, meta) {
              if (type === "display") {
                return `<div style="white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${data}</div>`;
              }
              return data;
            },
          },
        ],
      });
    }
  }, [mySchedules, pagination.total_count, pagination.page_size]);

  return (
    <div className="container-fluid w-100 mt-28">
      {error && <div className="alert alert-danger">{error}</div>}

      <div className="p-2 bg-white border rounded shadow-lg">
        <h4 className="p-2 m-2 text-center bg-white border rounded shadow-sm h4">
          <FontAwesomeIcon icon={faBell} /> Virtual Tours Scheduled
        </h4>

        <div className="gap-2 mb-3 d-flex justify-content-start">
          <button
            className="btn btn-outline-primary"
            onClick={() => handleTabChange("all")}
          >
            All Schedules
          </button>
          <button
            className="btn btn-primary"
            onClick={() => handleTabChange("my")}
          >
            My Schedules
          </button>
        </div>

        <div className="table-responsive">
          <div className="container">
            <table
              id="mySchedulesTable"
              ref={myTableRef}
              className="table table-striped table-bordered"
              style={{
                borderCollapse: "collapse",
                border: "2px solid #B0C4DE",
                width: "100%",
              }}
            >
              <thead style={{ backgroundColor: "#0056b3", color: "#fff", fontWeight: "bold" }}>
                <tr>
                  <th style={{ width: "5%" }}>#</th>
                  <th style={{ width: "25%" }}>Schedule By</th>
                  <th style={{ width: "25%" }}>Schedule With</th>
                  <th style={{ width: "35%" }}>Property Details</th>
                  <th style={{ width: "15%" }}>Time</th>
                </tr>
              </thead>
              <tbody></tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MySchedules;