import React, { useEffect, useState } from "react";
import $ from "jquery";
import "datatables.net-bs5";
import "bootstrap/dist/css/bootstrap.min.css";
import "datatables.net-bs5/css/dataTables.bootstrap5.min.css";
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
  faCheck, faTimes, faSpinner, faGift, faUser, faImage, faTag,
  faFileAlt, faCogs, faCircle, faCheckCircle, faTimesCircle
} from '@fortawesome/free-solid-svg-icons';
import Swal from 'sweetalert2';



const Offers = () => {
  const [offers, setOffers] = useState([]);
  const [errors, setErrors] = useState("");
  const [success, setSuccess] = useState("");

  useEffect(() => {
    fetchOffers();
  }, []);

  useEffect(() => {
    // Initialize or reinitialize the DataTable only when offer data is updated
    if (offers.length) {
      if ($.fn.DataTable.isDataTable("#dataTable")) {
        // Destroy the table if it already exists
        $("#dataTable").DataTable().destroy();
      }

      // Reinitialize the table after data update
      $("#dataTable").DataTable({
        paging: true,
        searching: true,
        info: true,
        lengthChange: true,
      });
    }
  }, [offers]);

  

  const fetchOffers = async () => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_BASE_URL}/api/get_offers`);
      if (!response.ok) {
        throw new Error("Failed to fetch data.");
      }

      const result = await response.json();
      if (result.status === 1 && Array.isArray(result.data)) {
        const offersStatus = result.data.map((offer) => ({
          ...offer,
          status: offer.status,
        }));

        setOffers(offersStatus);
      } else {
        setErrors("No data available.");
      }
    } catch (error) {
      console.error("Error fetching data:", error);
      setErrors("No data available.");
    }
  };

  const handleApproval = async (newStatus, _id) => {
    let proceed = false;
    let reason = "";

    if (newStatus === "Disapproved") {
      const { value: inputReason } = await Swal.fire({
        title: 'Reason for Disapproval',
        input: 'textarea',
        inputLabel: 'Please provide a reason for disapproving this offer',
        inputPlaceholder: 'Enter reason here...',
        showCancelButton: true,
        confirmButtonText: 'Submit',
        cancelButtonText: 'Cancel',
        inputValidator: (value) => {
          if (!value || value.trim() === "") {
            return 'A reason is required to disapprove the offer';
          }
        }
      });

      if (!inputReason) {
        return;
      }

      reason = inputReason;
      const confirmResult = await Swal.fire({
        title: `Confirm Status Change`,
        text: `Are you sure you want to change the status to ${newStatus}? Reason: ${reason}`,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonText: 'Yes, change it!',
        cancelButtonText: 'No, cancel'
      });

      proceed = confirmResult.isConfirmed;
    } else {
      const confirmResult = await Swal.fire({
        title: `Confirm Status Change`,
        text: `Are you sure you want to change the status to ${newStatus}?`,
        icon: 'question',
        showCancelButton: true,
        confirmButtonText: 'Yes, change it!',
        cancelButtonText: 'No, cancel'
      });

      proceed = confirmResult.isConfirmed;
    }

    if (proceed) {
      try {
        setSuccess("");
        setErrors("");

        const response = await fetch(`${process.env.REACT_APP_API_BASE_URL}/api/update_offer_status`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ offer_id: _id, status: newStatus, reason: newStatus === "Disapproved" ? reason : undefined }),
        });

        fetchOffers();

        if (!response.ok) {
          throw new Error("Failed to update status.");
        }

        Swal.fire({
          title: 'Success',
          text: newStatus === "Approved" 
            ? "The status has been successfully updated to Approved."
            : `The status has been successfully updated to Disapproved. Reason: ${reason}`,
          icon: 'success',
          confirmButtonText: 'OK'
        });

      } catch (error) {
        console.error("Error updating status:", error);
        Swal.fire({
          title: 'Error',
          text: 'Something went wrong.',
          icon: 'error',
          confirmButtonText: 'OK'
        });
      }
    }
  };
  return (
    <div className="w-100 container-fluid mt-28">
      {errors && <div className="alert alert-danger">{errors}</div>}
      {success && <div className="alert alert-success">{success}</div>}

      <div className="p-2 bg-white border rounded shadow-lg">
        <div>
          <h4 className="p-2 m-2 text-center bg-white border rounded shadow-sm h4">
            <FontAwesomeIcon icon={faGift} className="mr-2" /> Offers
          </h4>
        </div>

        <div>

          <table
            id="dataTable"
            className="table mt-3 table-striped table-bordered"
            style={{ borderCollapse: "collapse", border: "2px solid #B0C4DE" }}
          >
            <thead style={{ backgroundColor: "#0056b3", color: "#fff" }}>
              <tr>
                <th>#</th>
                <th ><FontAwesomeIcon icon={faImage} className="mr-2" /> Offer Image</th>
                <th><FontAwesomeIcon icon={faTag} className="mr-2" /> Offer Name</th>
                <th><FontAwesomeIcon icon={faFileAlt} className="mr-2" /> Offer Description</th>
                <th><FontAwesomeIcon icon={faCheckCircle} className="mr-2" /> Offer Status</th>
                <th><FontAwesomeIcon icon={faCogs} className="mr-2" /> Actions</th>
              </tr>
            </thead>
            <tbody>
              {offers.length > 0 ? (
                offers.map((offer, index) => (

                  <tr key={offer._id}>
                    <td>{index + 1}</td>
                    <td className="justify-content-center align-items-center" >
                      <img
                        src={`${process.env.REACT_APP_API_BASE_URL}` + offer.offer_img}
                        alt={offer.developer_name}
                        className="object-cover w-16 h-16 mr-4 rounded"
                      />
                    </td>
                    <td>
                      {offer.offer_name} <br />
                    </td>
                    <td>{offer.offer_description || "N/A"}</td>


                    <td
                      className={`h8 text-center ${offer.status === "Pending"
                          ? "text-info"
                          : offer.status === "Approved"
                            ? "text-success"
                            : "text-danger"
                        }`}
                    >
                      {offer.status === "Pending" && (
                        <span className="d-flex align-items-center justify-content-center">
                          <FontAwesomeIcon icon={faSpinner} spin className="mr-2" />
                          Pending
                        </span>
                      )}
                      {offer.status === "Approved" && (
                        <span className="d-flex align-items-center justify-content-center">
                          <FontAwesomeIcon icon={faCheckCircle} className="mr-2 text-success" />
                          Approved
                        </span>
                      )}
                      {offer.status === "Disapproved" && (
                        <span className="d-flex align-items-center justify-content-center">
                          <FontAwesomeIcon icon={faTimesCircle} className="mr-2 text-danger" />
                          Disapproved
                        </span>
                      )}
                    </td>
                    <td className="text-center">
                      <button
                        className={`btn ${offer.status === "Approved" ? "btn-danger" : "btn-success"} btn-sm`}
                        onClick={() =>
                          handleApproval(offer.status === "Approved" ? "Disapproved" : "Approved", offer._id)
                        }
                      >
                        {offer.status === "Approved" ? "✘" : "✔"}
                      </button>
                    </td>
                  </tr>

                ))
              ) : (
                <tr>
                  <td colSpan="7" className="text-center">
                    No data found
                  </td>
                </tr>
              )}
            </tbody>
          </table>
      
        </div>
      </div>
    </div>
  );
};

export default Offers;


