import React, { useState, useEffect, useRef, useCallback } from "react";
import axios from "axios";
import { useLoadScript, Autocomplete } from "@react-google-maps/api";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faPhone,faCog,
  faMapMarkerAlt,
  faInfoCircle,
  faEnvelope, 
} from "@fortawesome/free-solid-svg-icons";
import {
  faLinkedin,
  faFacebook,
  faYoutube,
  faInstagram,
  faTwitter,
  faPlaystation,
  faAppStore,
} from "@fortawesome/free-brands-svg-icons";

import { IoLogoGooglePlaystore } from "react-icons/io5";



const libraries = ["places"]; 

const GeneralSetting = () => {
  const [formData, setFormData] = useState({
    setting_id: "",
    free_view_count: "",
    free_post_count: "",
    contact: "",
    emaild_id: "",
    address: "",
    latitude: "",
    longitude: "",
    facebook: "",
    instagram: "",
    twitter: "",
    youtube: "",
    linkedin: "",
    about_houzza: "",
    playstore:"",
    appstore:"",
  });

  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const autocompleteRef = useRef(null); 

  const { isLoaded } = useLoadScript({
    googleMapsApiKey: 'AIzaSyCY4i1-nQFNVTSYetMw7aofzBRwGvCH_Ms',
    libraries,
  });

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_BASE_URL}/cust_api/get_setting`);
        if (response.data.status === 1) {
          const setting = response.data.data[0];
          setFormData({
            setting_id: setting._id,
            free_view_count: setting.free_view_count,
            free_post_count: setting.free_post_count,
            free_project_view_count: setting.free_project_view_count,
            free_project_post_count: setting.free_project_post_count,
            contact: setting.contact,
            emaild_id: setting.emaild_id,
            address: setting.address,
            latitude: setting.latitude,
            longitude: setting.longitude,
            facebook: setting.facebook,
            instagram: setting.instagram,
            twitter: setting.twitter,
            youtube: setting.youtube,
            linkedin: setting.linkedin,
            about_houzza: setting.about_houzza,
            playstore: setting.playstore,
            appstore: setting.appstore,
          });
        } else {
          setError("There was an error fetching the setting details!");
        }
      } catch (error) {
        setError("There was an error fetching the setting details!");
      }
    };

    fetchSettings();
  }, []);

  const handlePlaceSelect = useCallback(() => {
    if (autocompleteRef.current) {
      const place = autocompleteRef.current.getPlace();
      const address = place.formatted_address;
      const lat = place.geometry.location.lat();
      const lng = place.geometry.location.lng();

      setFormData((prevData) => ({
        ...prevData,
        address,
        latitude: lat,
        longitude: lng,
      }));
    }
  }, []);

  const handleChange = (e) => {
    const { id, value } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [id]: value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSuccess("");
    setError("");

    try {
      const formDataToSubmit = new FormData();
      Object.keys(formData).forEach((key) => {
        formDataToSubmit.append(key, formData[key]);
      });

      await axios.post(
        `${process.env.REACT_APP_API_BASE_URL}/cust_api/add_setting`,
        formDataToSubmit,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );

      setSuccess("Settings updated successfully!");
    } catch (error) {
      setError("There was an error updating the settings!");
    }
  };

  return (
    <div className="container-fluid w-100 mt-28">
      {error && <div className="alert alert-danger">{error}</div>}
      {success && <div className="alert alert-success">{success}</div>}

      <form
        onSubmit={handleSubmit}
        className="p-4 bg-white border rounded shadow-lg"
      >
        
        <div className="text-center">
          <h4 className="p-2 bg-white border rounded shadow-sm h4">
            <FontAwesomeIcon icon={faCog} className="mr-2 text-2xl " /> Update Settings
          </h4>
        </div>


        <div className="row">
          <div className="col-md-6">
            <InputField
              id="free_view_count"
              label="Free contacts view"
              type="number"
              value={formData.free_view_count}
              onChange={handleChange}
              required
            />
          </div>

          <div className="col-md-6">
            <InputField
              id="free_post_count"
              label="Free properties post"
              type="number"
              value={formData.free_post_count}
              onChange={handleChange}
              required
            />
          </div> 

          <div className="col-md-6">
            <InputField
              id="free_project_view_count"
              label="Free project contacts view"
              type="number"
              value={formData.free_project_view_count}
              onChange={handleChange}
              required
            />
          </div>

          <div className="col-md-6">
            <InputField
              id="free_project_post_count"
              label="Free project post count"
              type="number"
              value={formData.free_project_post_count}
              onChange={handleChange}
              required
            />
          </div>

          <div className="col-md-6">
              <label htmlFor="contact">
                <FontAwesomeIcon icon={faPhone} className="mr-2 text-black-500" /> Contact
              </label>
              <InputField
                id="contact"
                type="number"
                value={formData.contact}
                onChange={handleChange}
                required
              />
            </div>



          <div className="col-md-6">
            <label htmlFor="address">
            <FontAwesomeIcon icon={faMapMarkerAlt} className="mr-2 text-black-500" />
              Address
              </label>
            {isLoaded && (
              <Autocomplete
                onLoad={(autocomplete) => (autocompleteRef.current = autocomplete)}
                onPlaceChanged={handlePlaceSelect}
              >
                <input
                  id="address"
                  className="form-control"
                  value={formData.address}
                  onChange={(e) =>
                    setFormData({ ...formData, address: e.target.value })
                  }
                  required
                />
              </Autocomplete>
            )}
            <input
              type="hidden"
              name="latitude"
              value={formData.latitude}
            />
            <input
              type="hidden"
              name="longitude"
              value={formData.longitude}
            />
          </div>
         
          <div className="col-md-6">
          <label htmlFor="email">
                <FontAwesomeIcon icon={faEnvelope} className="mr-2 text-black-500" /> Email
              </label>
          <InputField
            id="emaild_id"
            value={formData.emaild_id}
            onChange={handleChange}
            required
          />
        </div>
         
           <div className="col-md-6">
             <label htmlFor="about_houzza">
               <FontAwesomeIcon icon={faInfoCircle} className="mr-2 text-black-500" /> About Houzza
             </label>
             <textarea
              id="about_houzza"
              className="form-control"
              value={formData.about_houzza}
              onChange={handleChange}
            />
          </div>



          
          <div className="col-md-6">
             <InputField
              id="linkedin"
              label={
                <>
                  <FontAwesomeIcon icon={faLinkedin} className="mr-2" /> LinkedIn URL
                </>
              }
              value={formData.linkedin}
              onChange={handleChange}
              required
            />
          </div>


          <div className="col-md-6">
             <InputField
              id="facebook"
              label={
                <>
                  <FontAwesomeIcon icon={faFacebook} className="mr-2" /> Facebook URL
                </>
              }
              value={formData.facebook}
              onChange={handleChange}
              required
            />
          </div>

        
          <div className="col-md-6">
             <InputField
              id="youtube"
              label={
                <>
                  <FontAwesomeIcon icon={faYoutube} className="mr-2" /> YouTube URL
                </>
              }
              value={formData.youtube}
              onChange={handleChange}
              required
            />
          </div>

          <div className="col-md-6">
            <InputField
              id="instagram"
              label={
                <>
                  <FontAwesomeIcon icon={faInstagram} className="mr-2" /> Instagram URL
                </>
              }
              value={formData.instagram}
              onChange={handleChange}
              required
            />
          </div>

          <div className="col-md-6">
            <InputField
              id="twitter"
              label={
                <>
                  <FontAwesomeIcon icon={faTwitter} className="mr-2" /> Twitter URL
                </>
              }
              value={formData.twitter}
              onChange={handleChange}
              required
            />
          </div> 

          <div className="col-md-6">
            <InputField
              id="twitter"
              label={
                <>
                  <FontAwesomeIcon icon={faTwitter} className="mr-2" /> Twitter URL
                </>
              }
              value={formData.twitter}
              onChange={handleChange}
              required
            />
          </div>
          <div className="col-md-6">
            <InputField
              id="playstore"
              label={
                <>
                  <IoLogoGooglePlaystore className="mr-2" /> Playstore URL
                </>
              }
              value={formData.playstore}
              onChange={handleChange}
              required
            />
          </div>
          <div className="col-md-6">
            <InputField
              id="appstore"
              label={
                <>
                  <FontAwesomeIcon icon={faAppStore} className="mr-2" /> Appstore URL
                </>
              }
              value={formData.playstore}
              onChange={handleChange}
              required
            />
          </div>




        </div>
        <div className="mt-4 text-start">
          <button type="submit" className="btn btn-primary">
            Update
          </button>
        </div>
      </form>
    </div>
  );
};

const InputField = ({ id, label, type = "text", value, onChange }) => (
  <div className="mb-4 form-group">
    <label htmlFor={id}>{label}</label>
    <input
      id={id}
      type={type}
      value={value}
      onChange={onChange}
      className="form-control"
    />
  </div>
);

export default GeneralSetting;

