import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import PropertyCard from "./PropertyCard";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faPlus, faWarehouse } from "@fortawesome/free-solid-svg-icons";
import { useNavigate } from "react-router-dom";
import { IoIosSearch,IoMdClose } from "react-icons/io";


const Properties = () => {
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [success, setSuccessMessage] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [isFetching, setIsFetching] = useState(false);
  const [searchKeyword, setSearchKeyword] = useState("");
  const [category, setCategory] = useState("");
  const [city, setCity] = useState("");
  const [locality, setLocality] = useState("");
  const [propertyType, setPropertyType] = useState("");
  const [minPrice, setMinPrice] = useState("");
  const [maxPrice, setMaxPrice] = useState("");
  const [furnishType, setFurnishType] = useState([]);
  const [bhkType, setBhkType] = useState([]);
  const [sortBy, setSortBy] = useState("");
  const [showFurnishDropdown, setShowFurnishDropdown] = useState(false);
  const [showBhkDropdown, setShowBhkDropdown] = useState(false);
  const navigate = useNavigate();
  const observerRef = useRef(null);
  const loadMoreRef = useRef(null);
  const firstLoad = useRef(true);
  const useFilterApi = useRef(false);
  const userId = sessionStorage.getItem("accessToken") || "67f0ff69d7908f15767d3e64";
   const [priceError, setPriceError] = useState("");

  const priceOptions = [
    { label: "₹ 5 Lakhs", value: 500000 },
    { label: "₹ 10 Lakhs", value: 1000000 },
    { label: "₹ 15 Lakhs", value: 1500000 },
    { label: "₹ 20 Lakhs", value: 2000000 },
    { label: "₹ 25 Lakhs", value: 2500000 },
    { label: "₹ 30 Lakhs", value: 3000000 },
    { label: "₹ 40 Lakhs", value: 4000000 },
    { label: "₹ 50 Lakhs", value: 5000000 },
    { label: "₹ 60 Lakhs", value: 6000000 },
    { label: "₹ 75 Lakhs", value: 7500000 },
    { label: "₹ 90 Lakhs", value: 9000000 },
    { label: "₹ 1 Crore", value: 10000000 },
    { label: "₹ 1.25 Crore", value: 12500000 },
    { label: "₹ 1.5 Crore", value: 15000000 },
    { label: "₹ 1.75 Crore", value: 17500000 },
    { label: "₹ 2 Crore", value: 20000000 },
    { label: "₹ 3 Crore", value: 30000000 },
    { label: "₹ 4 Crore", value: 40000000 },
    { label: "₹ 5 Crore", value: 50000000 },
    { label: "₹ 10 Crore", value: 100000000 },
    { label: "₹ 20 Crore", value: 200000000 },
    { label: "₹ 30 Crore", value: 300000000 },
    { label: "₹ 50 Crore", value: 500000000 },
    { label: "₹ 75 Crore", value: 750000000 },
  ];

  useEffect(() => {
    // Retrieve and clear success message from localStorage
    const message = localStorage.getItem("success");
    if (message) {
      setSuccessMessage(message);
      setTimeout(() => setSuccessMessage(""), 2000);
      localStorage.removeItem("success");
    }
  }, []);

  useEffect(() => {
    // Determine if filters or search are active
    const hasFiltersOrSearch = searchKeyword || category || city || locality || propertyType || minPrice || maxPrice || furnishType.length > 0 || bhkType.length > 0 || sortBy;

    // On first load or when all filters/search are cleared, use get-listing-properties
    if (firstLoad.current || !hasFiltersOrSearch) {
      useFilterApi.current = false;
      setProperties([]);
      setCurrentPage(1);
      fetchProperties(1, true); // true for get-listing-properties
      firstLoad.current = false;
    } else {
      // Use my_properties_search_filter when filters or search are active
      useFilterApi.current = true;
      setProperties([]);
      setCurrentPage(1);
      fetchProperties(1, false); // false for my_properties_search_filter
    }
  }, [category, city, locality, propertyType, minPrice, maxPrice, searchKeyword, furnishType, bhkType, sortBy]);

  useEffect(() => {
    // Set up Intersection Observer for lazy loading
    if (observerRef.current) observerRef.current.disconnect();

    observerRef.current = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !isFetching && currentPage < totalPages) {
          fetchProperties(currentPage + 1, !useFilterApi.current);
        }
      },
      { threshold: 0.1 }
    );

    if (loadMoreRef.current) {
      observerRef.current.observe(loadMoreRef.current);
    }

    return () => {
      if (observerRef.current) observerRef.current.disconnect();
    };
  }, [currentPage, totalPages, isFetching]);

  const fetchProperties = async (page, useGetListing = false) => {
    setIsFetching(true);
    setError("");
    try {
      const formData = new FormData();
      formData.append("page", page.toString());
      formData.append("page_size", "8");

      // Use my_properties_search_filter only if filters or search are active
      let endpoint = `${process.env.REACT_APP_API_BASE_URL}/cust_api/get-listing-properties-admin`;
      if (!useGetListing) {
        if (searchKeyword) formData.append("search_keyword", searchKeyword);
        if (category) formData.append("property_category_type", category);
        if (city) formData.append("city_name", city);
        if (locality) formData.append("address", locality);
        if (propertyType) formData.append("property_type", propertyType);
        if (minPrice) formData.append("min_price", minPrice);
        if (maxPrice) formData.append("max_price", maxPrice);
        if (furnishType.length > 0) formData.append("furnish_type", furnishType.join("|"));
        if (bhkType.length > 0) formData.append("bhk_type", bhkType.join("|"));
        if (sortBy) formData.append("sort_by", sortBy);
        endpoint = `${process.env.REACT_APP_API_BASE_URL}/cust_api/my_properties_search_filter_admin`;
      }

      const response = await axios.post(endpoint, formData);
      console.log("API Response:", response.data); // Debug log to inspect response

      if (response.data.status === 1) {
        const transformed = response.data.data.map((item) => ({
          _id: item._id,
          property_name: item.property_name,
          address: item.address,
          created_at: item.created_at,
          cover_image: item.cover_image
            ? item.cover_image.startsWith("http")
              ? item.cover_image
              : `${process.env.REACT_APP_API_BASE_URL}/${item.cover_image}`
            : "https://via.placeholder.com/150",
          logo: item.logo
            ? item.logo.startsWith("http")
              ? item.logo
              : `${process.env.REACT_APP_API_BASE_URL}/${item.logo}`
            : "https://via.placeholder.com/55",
          admin_approval: item.admin_approval,
          property_category_type: item.property_category_type,
          property_type: item.property_type,
          bhk_type: item.bhk_type || "Not Specified",
          property_price: item.property_price,
          view_count: item.view_count,
          leads_count: item.leads_count,
          property_description: item.property_description,
          building_type: item.building_type,
          days_since_created: item.days_since_created,
          address_area: item.address_area,
          property_owner_image: item.property_owner_image,
          connect_to_name: item.connect_to_name,
          user_type: item.user_type,
        }));

        setTotalPages(response.data.total_pages || 1);
        setCurrentPage(response.data.current_page);
        setProperties((prevProperties) => [
          ...prevProperties,
          ...transformed
        ]);
      } else {
        setProperties([]);
        setTotalPages(1);
        setError(response.data.msg || "No properties found.");
      }
    } catch (error) {
      console.error("There was an error fetching the properties!", error);
      setError("There was an error fetching the properties");
    } finally {
      setLoading(false);
      setIsFetching(false);
    }
  };

  const handleSearch = () => {
    setProperties([]);
    setCurrentPage(1);
    useFilterApi.current = true;
    fetchProperties(1, false); // Use my_properties_search_filter for search
  };

  const handleDelete = async (propertyId) => {
    try {
      const response = await axios.delete(
        `${process.env.REACT_APP_API_BASE_URL}/cust_api/delete_listing_property`,
        {
          data: {
            property_id: propertyId,
          },
        }
      );

      if (response.data.status === 1) {
        setProperties(properties.filter((property) => property._id !== propertyId));
        setSuccessMessage("Property deleted successfully.");
        setTimeout(() => setSuccessMessage(""), 2000);
      } else {
        setError("Error deleting property");
      }
    } catch (error) {
      console.error("Error deleting property", error);
      setError("Error deleting property");
    }
  };


  // Close dropdowns when clicking outside
  const furnishDropdownRef = useRef(null);
  const bhkDropdownRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (furnishDropdownRef.current && !furnishDropdownRef.current.contains(event.target)) {
        setShowFurnishDropdown(false);
      }
      if (bhkDropdownRef.current && !bhkDropdownRef.current.contains(event.target)) {
        setShowBhkDropdown(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

   const handleMinChange = (e) => {
  const value = Number(e.target.value);
  setMinPrice(value);

  if (maxPrice && value > maxPrice) {
   setPriceError("Min price should not be greater than Max price");
  } else {
   setPriceError("");
  }
 };

 const handleMaxChange = (e) => {
  const value = Number(e.target.value);
  setMaxPrice(value);

  if (minPrice && value < minPrice) {
   setPriceError("Max price should not be less than Min price");
  } else {
   setPriceError("");
  }
 };


  return (
    <div className="w-100 container-fluid mt-28">
      {error && <div className="alert alert-danger">{error}</div>}
      {success && <div className="alert alert-success">{success}</div>}
      {loading && <div className="alert alert-secondary">Loading...</div>}

      <div className="w-full">
        <div className="flex items-center justify-between">
          <hr className="w-1/4 border-t-2 border-black" />
          <div className="flex items-center space-x-4">
            <FontAwesomeIcon icon={faWarehouse} className="mb-3 text-black-500 fa-2x" />
            <p className="text-3xl font-bold text-black">My Inventory</p>
          </div>
          <hr className="w-1/4 border-t-2 border-black" />
        </div>

        <div className="p-3">
          <div className="flex flex-col justify-between mb-4 md:flex-row md:items-center">
             <div className="relative md:mt-0">
      <IoIosSearch
       className="absolute text-gray-500 transform -translate-y-1/2 cursor-pointer left-3 top-1/2"
       onClick={handleSearch}
      />
      <input
       type="text"
       placeholder="Search"
       value={searchKeyword}
       onChange={(e) => {
        const value = e.target.value;
        setSearchKeyword(value);
        handleSearch(); // Trigger search as user types
       }}
       className="px-10 py-2 pr-10 border rounded-lg outline-none w-72 focus:ring-2 focus:ring-purple-400"
      />
      {searchKeyword && (
       <button
        onClick={() => {
         setSearchKeyword("");
         fetchProperties();
        }}
        className="absolute text-lg text-gray-500 transform -translate-y-1/2 right-3 top-1/2 hover:text-gray-900"
       >
        <IoMdClose />
       </button>
      )}
     </div>
            <div className="flex gap-4 mt-4 md:mt-0">
              <button
                onClick={() => navigate("/amenities")}
                className="px-4 py-2 font-bold text-white bg-blue-500 rounded hover:bg-blue-700 focus:outline-none focus:shadow-outline"
              >
                Amenities
              </button>
              <button
                onClick={() => navigate("/add-property")}
                className="px-4 py-2 font-bold text-white bg-blue-500 rounded hover:bg-blue-700 focus:outline-none focus:shadow-outline"
              >
                <FontAwesomeIcon icon={faPlus} /> Add Property
              </button>
            </div>
          </div>

          <div className="flex flex-wrap justify-around mt-6 gap-9">
            <select
              className="w-40 px-2 py-2 border rounded-lg outline-none"
              value={category}
              onChange={(e) => setCategory(e.target.value)}
            >
              <option value="">Category Type</option>
              <option value="Buy">Buy</option>
              <option value="Rent">Rent</option>
            </select>
            <select
              className="w-32 px-2 py-2 border rounded-lg outline-none"
              value={city}
              onChange={(e) => setCity(e.target.value)}
            >
              <option value="">City</option>
              <option value="Mumbai">Mumbai</option>
              <option value="Pune">Pune</option>
              <option value="Delhi">Delhi</option>
              <option value="Bangalore">Bangalore</option>
              <option value="Chennai">Chennai</option>
              <option value="Hyderabad">Hyderabad</option>
              <option value="Kolkata">Kolkata</option>
              <option value="Ahmedabad">Ahmedabad</option>
            </select>
            <div className="w-0 md:w-40"></div>
            {/* <div className="relative md:mt-0">
            <input
              type="text"
              placeholder="Enter locality or projects"
              value={locality}
              onChange={(e) => setLocality(e.target.value)}

              className="w-64 px-4 py-2 border rounded-lg outline-none"
            />
            {locality && (
              <button
                onClick={() => {
                  setLocality("");
                }}
                className="absolute text-lg text-gray-500 transform -translate-y-1/2 right-3 top-1/2 hover:text-gray-900"
              >
                <IoMdClose />
              </button>
            )}
          </div> */}
            <select
              className="w-40 px-2 py-2 border rounded-lg outline-none"
              value={propertyType}
              onChange={(e) => setPropertyType(e.target.value)}
            >
              <option value="">Property Type</option>
              <option value="Apartment">Apartment</option>
              <option value="Plot">Plot</option>
              <option value="Villa">Villa</option>
              <option value="Independent House">Independent House</option>
              <option value="Builder Floor">Builder Floor</option>
              <option value="Penthouse">Penthouse</option>
              <option value="Office Space">Office Space</option>
              <option value="Shop">Shop</option>
              <option value="Land">Land</option>
              <option value="Office Space IT/SEZ">Office Space IT/SEZ</option>
              <option value="Showroom">Showroom</option>
              <option value="Warehouse">Warehouse</option>
              <option value="Industrial Plot">Industrial Plot</option>
              <option value="Working Space">Co-Working Space</option>
              <option value="PG">PG</option>
            </select>
            <div>
              <select
                value={minPrice}
                onChange={handleMinChange}
                className="px-2 py-2 border rounded-lg outline-none w-28"
              >
                <option value="">₹ Min</option>
                {priceOptions.map((option, index) => (
                  <option key={index} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
              &nbsp;&nbsp;&nbsp;
              <select
                value={maxPrice}
                onChange={handleMaxChange}
                className="px-2 py-2 border rounded-lg outline-none w-28"
              >
                <option value="">₹ Max</option>
                {priceOptions.map((option, index) => (
                  <option key={index} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
              {priceError && (
                <p className="mt-1 text-sm text-red-500">{priceError}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 gap-4 mt-4 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-3">
            {Array.isArray(properties) && properties.length > 0 ? (
              properties.map((property) => (
                <PropertyCard
                  key={property._id}
                  property={property}
                  onDelete={handleDelete}
                />
              ))
            ) : (
              <p className="text-center text-gray-500">No properties found</p>
            )}
          </div>

          {currentPage < totalPages && (
            <div ref={loadMoreRef} className="h-10"></div>
          )}

          {isFetching && (
            <div className="mt-4 text-center">
              <div className="alert alert-secondary">Loading more properties...</div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Properties;