import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import "bootstrap/dist/css/bootstrap.min.css";
import $ from "jquery"; // jQuery for DataTables
import "datatables.net-bs5"; // DataTables with Bootstrap 5 styling
import "datatables.net-responsive-bs5"; // For responsive DataTables
import "datatables.net-bs5/css/dataTables.bootstrap5.min.css"; // DataTables CSS

// Import FontAwesome Icons
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faUser,
  faEnvelope,
  faStar,
  faCommentDots,
} from "@fortawesome/free-solid-svg-icons";

const FeedbackList = () => {
  const [feedbacks, setFeedbacks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [sortOrder, setSortOrder] = useState("asc");

  // Reference to the table DOM element
  const tableRef = useRef(null);
  // Reference to DataTable instance
  const dataTableRef = useRef(null);

  useEffect(() => {
    const fetchFeedbacks = async () => {
      try {
        const response = await axios.get(
          `${process.env.REACT_APP_API_BASE_URL}/api/get_feedbacks`
        );
        if (response.data.status === 1) {
          setFeedbacks(response.data.data); // Set feedbacks data
        } else {
          setError("No data available");
        }
      } catch (error) {
        console.error("There was an error fetching the feedbacks!", error);
        setError("There was an error fetching the feedbacks");
      } finally {
        setLoading(false);
      }
    };

    fetchFeedbacks();
  }, []); // Only fetch feedbacks on component mount

  useEffect(() => {
    // Initialize DataTable after feedbacks have been fetched
    if (!loading && !error && feedbacks.length > 0) {
      // Check if DataTable is already initialized
      if (dataTableRef.current) {
        dataTableRef.current.destroy(); // Destroy existing DataTable instance
      }

      // Initialize DataTable
      dataTableRef.current = $(tableRef.current).DataTable({
        paging: true,
        searching: true,
        responsive: true,
        destroy: true, // Ensure table is destroyed when re-rendering
        // Optional: Customize DataTable options here
        // For example, to set initial sorting:
        // order: [[3, 'desc']], // Sort by Rating descending
        // To set page length:
        // pageLength: 10,
      });
    }

    // Cleanup function to destroy DataTable on component unmount or when feedbacks change
    return () => {
      if (dataTableRef.current) {
        dataTableRef.current.destroy();
        dataTableRef.current = null;
      }
    };
  }, [loading, error, feedbacks]);

  return (
    <div className="container-fluid mt-28 w-100">
      {error && <div className="alert alert-danger">{error}</div>}
      <div className="p-2 bg-white border rounded shadow-lg">
        <h4 className="p-2 m-2 text-center bg-white border rounded shadow-sm h4">
          <FontAwesomeIcon icon={faCommentDots} className="mr-2" /> Feedback
          List
        </h4>

        <div>
          <table
            ref={tableRef}
            className="table mt-3 table-striped table-bordered"
            style={{ borderCollapse: "collapse", border: "2px solid #B0C4DE" }}
          >
            <thead style={{ backgroundColor: "#0056b3", color: "white" }}>
              <tr>
                <th>#</th>
                <th>
                  <FontAwesomeIcon icon={faUser} className="mr-2" />
                 User Name
                </th>
                <th>
                  <FontAwesomeIcon icon={faEnvelope} className="mr-2" />
                  Email
                </th>
                <th
                  onClick={() =>
                    setSortOrder((prev) => (prev === "asc" ? "desc" : "asc"))
                  }
                  style={{ cursor: "pointer" }}
                >
                  <FontAwesomeIcon icon={faStar} className="mr-2" />
                  Rating {sortOrder === "desc"}
                </th>
                <th>
                  <FontAwesomeIcon icon={faCommentDots} className="mr-2" />
                  Feedback
                </th>
              </tr>
            </thead>
            <tbody>
              {feedbacks.length > 0 ? (
                [...feedbacks]
                  .sort((a, b) =>
                    sortOrder === "asc"
                      ? a.rating - b.rating
                      : b.rating - a.rating
                  )
                  .map((feedback, index) => (
                    <tr key={feedback._id}>
                      <td>{index + 1}</td>
                      <td>{feedback.name}</td>
                      <td>{feedback.email}</td>
                      <td>
                        {Array.from({ length: 5 }, (_, i) => (
                          <FontAwesomeIcon
                            key={i}
                            icon={faStar}
                            className={
                              i < feedback.rating
                                ? "text-warning"
                                : "text-muted"
                            }
                          />
                        ))}
                      </td>
                      <td>{feedback.feedback_msg}</td>
                    </tr>
                  ))
              ) : (
                <tr>
                  <td colSpan="5" className="text-center">
                    No feedbacks found
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default FeedbackList;

