import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faImage,
  faTag,
  faDollarSign,
  faThList,
  faToggleOn,
  faCalendarAlt,
  faCalendarDay,
  faPercentage,
  faBoxes,
  faCogs,
  faInfoCircle,
  faSave,
  faTimesCircle,
  faPlusCircle,
  faPen,
  faCancel,
} from "@fortawesome/free-solid-svg-icons";
import { Link } from "react-router-dom";

const UpdatePlan = () => {
  const { plan_id } = useParams();
  const navigate = useNavigate();

  const [plan, setPlan] = useState({
    plan_image: "",
    plan_name: "",
    category_type: "",
    features: "",
    plan_price: "",
    final_price: "",
    validity: "",
    validity_unit: "",
    offer_percentage: "",
    description: "",
    no_of_units: "",
    status: "",
  });

  const [imagePreview, setImagePreview] = useState(null);

  // Fetch existing plan details based on plan_id
  useEffect(() => {
    const fetchPlanDetails = async () => {
      try {
        const bodyData = JSON.stringify({
          plan_id: plan_id, // Sending plan_id as 'plan_id'
        });

        const response = await fetch(
          `${process.env.REACT_APP_API_BASE_URL}/api/get_plan_details`,
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: bodyData,
          }
        );

        console.log("Request Body:", bodyData); // Log the request body to debug
        console.log("plan_id:", plan_id); // Log the plan_id to ensure it's correct

        if (response.ok) {
          const data = await response.json();
          console.log("Plan details:", data); // Log the response for debugging
          setPlan(data.data); // Set the plan details in state

          if (data.data.plan_image) {
            setImagePreview(
              `${process.env.REACT_APP_API_BASE_URL}${data.data.plan_image}`
            ); // Correct image preview URL
          }
        } else {
          const errorData = await response.text();
          console.error("Error fetching plan details:", errorData);
        }
      } catch (error) {
        console.error("Error during API call:", error);
      }
    };

    if (plan_id) {
      // Only fetch if plan_id is available
      fetchPlanDetails();
    }
  }, [plan_id]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setPlan({
      ...plan,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Prepare the form data for the update request
    const formData = new FormData();
    formData.append("plan_id", plan_id);
    formData.append("plan_image", plan.plan_image);
    formData.append("plan_name", plan.plan_name);
    formData.append("category_type", plan.category_type);
    formData.append("features", plan.features);
    formData.append("plan_price", plan.plan_price);
    formData.append("final_price", plan.final_price);
    formData.append("validity", plan.validity);
    formData.append("validity_unit", plan.validity_unit);
    formData.append("offer_percentage", plan.offer_percentage);
    formData.append("description", plan.description);
    formData.append("no_of_units", plan.no_of_units);
    formData.append("status", plan.status);

    try {
      const response = await fetch(
        `${process.env.REACT_APP_API_BASE_URL}/api/update_plan`,
        {
          method: "POST",
          body: formData,
        }
      );

      if (response.ok) {
        const data = await response.json();
        console.log("Plan updated successfully:", data.msg);
        localStorage.setItem("success", data.msg);
        navigate("/plans-purchase");
      } else {
        const data = await response.json();
        console.error("Error while updating plan!", data);
      }
    } catch (error) {
      console.error("Error during submission:", error);
      alert("Failed to update the plan. Please try again.");
    }
  };

  return (
    <div className="w-100 container-fluid mt-28">
      {/* Breadcrumb aligned right */}
      <nav className="flex justify-end mb-4" aria-label="Breadcrumb">
        <ol className="flex flex-wrap items-center space-x-2 md:space-x-4 text-sm">
          <li>
            <Link
              to="/plans-purchase"
              className="text-blue-600 font-medium hover:underline transition-colors"
            >
              Go TO Plans
            </Link>
          </li>

          <li className="text-gray-400">/</li>

          <li>
            <span className="inline-block px-3 py-1 rounded-full text-gray-800 font-bold text-base">
              Edit Plan Page
            </span>
          </li>
        </ol>
      </nav>

      <form
        onSubmit={handleSubmit}
        className="p-2 bg-white border rounded shadow-lg"
      >
        <div className="text-center">
          <h4 className="p-2 m-2 bg-white border rounded shadow-sm h4">
            <FontAwesomeIcon icon={faPen} className="mr-2" />
            Update Plan
          </h4>
        </div>
        <div className="row">
          <div className="col-md-6">
            <div className="mb-3 d-flex align-items-center">
              <div className="mb-3">
                <label
                  htmlFor="plan_image"
                  className="form-label font-weight-bold"
                >
                  <FontAwesomeIcon icon={faImage} className="mr-2" />
                  Plan Image
                </label>
                <input
                  type="file"
                  className="form-control"
                  id="plan_image"
                  name="plan_image"
                  onChange={(e) =>
                    setPlan({ ...plan, plan_image: e.target.files[0] })
                  }
                />
              </div>

              {/* Image preview */}
              {imagePreview && (
                <div className="ms-3">
                  <img
                    src={imagePreview} // Direct URL set in useEffect
                    alt="Plan"
                    style={{ maxWidth: "100px", maxHeight: "100px" }}
                  />
                </div>
              )}
            </div>

            <div className="mb-3">
              <label
                htmlFor="plan_name"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faTag} className="mr-2" />
                Plan Name <sup className="text-danger">*</sup>
              </label>
              <input
                type="text"
                className="form-control"
                id="plan_name"
                name="plan_name"
                value={plan.plan_name}
                onChange={handleChange}
                required
              />
            </div>

            <div className="mb-3">
              <label
                htmlFor="category_type"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faThList} className="mr-2" />
                Plan Category Type <sup className="text-danger">*</sup>
              </label>
              <select
                className="form-select"
                id="category_type"
                name="category_type"
                value={plan.category_type}
                onChange={handleChange}
                required
                disabled
              >
                <option value="" disabled>
                  Select a category
                </option>
                <option value="Post Properties">Post Properties</option>
                <option value="Top Developers">Top Developers</option>
                <option value="Upcoming Projects">Upcoming Projects</option>
                <option value="Featured Properties">Featured Properties</option>
                <option value="Advertising">Advertising</option>
                <option value="Offers">Offers</option>
              </select>
            </div>

            <div className="mb-3">
              <label
                htmlFor="plan_price"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faDollarSign} className="mr-2" />
                Plan Price <sup className="text-danger">*</sup>
              </label>
              <input
                type="number"
                className="form-control"
                id="plan_price"
                name="plan_price"
                value={plan.plan_price}
                onChange={handleChange}
                required
              />
            </div>

            <div className="mb-3">
              <label
                htmlFor="final_price"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faDollarSign} className="mr-2" />
                Final Price <sup className="text-danger">*</sup>
              </label>
              <input
                type="number"
                className="form-control"
                id="final_price"
                name="final_price"
                value={plan.final_price}
                onChange={handleChange}
                required
              />
            </div>

            <div className="mb-3">
              <label htmlFor="status" className="form-label font-weight-bold">
                <FontAwesomeIcon icon={faToggleOn} className="mr-2" />
                Plan Status <sup className="text-danger">*</sup>
              </label>
              <select
                className="form-select"
                id="status"
                name="status"
                value={plan.status}
                onChange={handleChange}
                required
              >
                <option value="" disabled>
                  Select status
                </option>
                <option value="Active">Active</option>
                <option value="Inactive">Inactive</option>
              </select>
            </div>
          </div>

          <div className="col-md-6">
            <div className="mb-3 row">
              <div className="col-md-6">
                <label
                  htmlFor="validity"
                  className="form-label font-weight-bold"
                >
                  <FontAwesomeIcon icon={faCalendarAlt} className="mr-2" />
                  Validity <sup className="text-danger">*</sup>
                </label>
                <input
                  type="number"
                  className="form-control"
                  id="validity"
                  name="validity"
                  value={plan.validity}
                  onChange={handleChange}
                  required
                />
              </div>
              <div className="col-md-6">
                <label
                  htmlFor="validity_unit"
                  className="form-label font-weight-bold"
                >
                  <FontAwesomeIcon icon={faCalendarDay} className="mr-2" />
                  Validity In <sup className="text-danger">*</sup>
                </label>
                <select
                  className="form-select"
                  id="validity_unit"
                  name="validity_unit"
                  value={plan.validity_unit}
                  onChange={handleChange}
                  required
                  disabled
                >
                  <option value="" disabled>
                    Select Unit
                  </option>
                  <option value="Days">Days</option>
                  <option value="Month">Month</option>
                  <option value="Year">Year</option>
                </select>
              </div>
            </div>

            <div className="mb-3">
              <label
                htmlFor="offer_percentage"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faPercentage} className="mr-2" />
                Offer Percentage <sup className="text-danger">*</sup>
              </label>
              <input
                type="number"
                className="form-control"
                id="offer_percentage"
                name="offer_percentage"
                value={plan.offer_percentage}
                onChange={handleChange}
                required
              />
            </div>

            <div className="mb-3">
              <label
                htmlFor="no_of_units"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faBoxes} className="mr-2" />
                Number Of Units <sup className="text-danger">*</sup>
              </label>
              <input
                type="number"
                className="form-control"
                id="no_of_units"
                name="no_of_units"
                value={plan.no_of_units}
                onChange={handleChange}
                required
              />
            </div>

            <div className="mb-3">
              <label htmlFor="features" className="form-label font-weight-bold">
                <FontAwesomeIcon icon={faCogs} className="mr-2" />
                Features <sup className="text-danger">*</sup>
              </label>
              <textarea
                className="form-control"
                id="features"
                name="features"
                value={plan.features}
                onChange={handleChange}
                required
                placeholder="Separate features with a comma"
              ></textarea>
            </div>

            <div className="mb-3">
              <label
                htmlFor="description"
                className="form-label font-weight-bold"
              >
                <FontAwesomeIcon icon={faInfoCircle} className="mr-2" />
                Description <sup className="text-danger">*</sup>
              </label>
              <textarea
                className="form-control"
                id="description"
                name="description"
                value={plan.description}
                onChange={handleChange}
                required
              ></textarea>
            </div>
          </div>
        </div>

        <div className="text-center">
          <button type="submit" className="mt-4 btn btn-primary">
            <FontAwesomeIcon icon={faPen} className="mr-2" />
            Update
          </button>

          <button
            onClick={() => navigate("/plans-purchase")}
            className="mt-4 btn btn-secondary mx-2"
          >
            <FontAwesomeIcon icon={faTimesCircle} className="mr-2" />
            Cancel
          </button>
        </div>
      </form>
    </div>
  );
};

export default UpdatePlan;
