import React, { useState, useEffect } from 'react';
import { EditorState, ContentState, convertFromHTML } from 'draft-js';
import TextEditor from './TextEditor';
import { stateToHTML } from 'draft-js-export-html';
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faInfoCircle } from '@fortawesome/free-solid-svg-icons';

const AboutUsForm = () => {
    const [editorState, setEditorState] = useState(EditorState.createEmpty());
    const [aboutId, setAboutId] = useState('');
    const [error, setError] = useState(null);
    const [successMessage, setSuccessMessage] = useState(null);

    // Fetch the existing About Us content
    const fetchContent = () => {
        fetch(`${process.env.REACT_APP_API_BASE_URL}/cust_api/get-about-us`)
            
            .then((response) => response.json())
            .then((data) => {
                if (data.status === 1 && data.data.length > 0) {
                    const aboutData = data.data[0];
                    setAboutId(aboutData._id);

                    // Initialize editor with fetched HTML content
                    const blocksFromHTML = convertFromHTML(aboutData.content);
                    const contentState = ContentState.createFromBlockArray(
                        blocksFromHTML.contentBlocks,
                        blocksFromHTML.entityMap
                    );
                    setEditorState(EditorState.createWithContent(contentState));
                }
            })
            .catch((error) => {
                console.error('Error fetching About Us content:', error);
                setError('Failed to fetch About Us content.');
            });
    };

    useEffect(() => {
        fetchContent();
    }, []);

    // Handle form submission
    const handleSubmit = (e) => {
        e.preventDefault();

        const contentState = editorState.getCurrentContent();
        const htmlContent = stateToHTML(contentState); // Convert contentState to HTML
        setSuccessMessage('');
        setError('');

        // Prepare payload for API
        const payload = {
            content: htmlContent, // Store as HTML
            about_id: aboutId
        };

        // POST request to save the updated About Us content
        fetch(`${process.env.REACT_APP_API_BASE_URL}/api/add_about`, {
           
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(payload),
        })
            .then((response) => response.json())
            .then((data) => {
                if (data.status === 1) {
                    setSuccessMessage('About Us updated successfully');
                    fetchContent(); // Refetch the updated content
                } else {
                    setError('Failed to update About Us.');
                }
            })
            .catch((error) => {
                console.error('Error updating About Us:', error);
                setError('Failed to update About Us.');
            });
    };

    return (
        <div className="w-100 container-fluid mt-28">
            {error && <div className="alert alert-danger">{error}</div>}
            {successMessage && <div className="alert alert-success">{successMessage}</div>}

            <form onSubmit={handleSubmit} className="p-2 bg-white border rounded shadow-lg">
                <div className="row">
                    <div className="col-md-12">
                        <h4 className="p-2 m-2 text-center bg-white border rounded shadow-sm h4">
                            <FontAwesomeIcon icon={faInfoCircle} className="mr-2 text-black-500" />
                            About Us
                        </h4>
                    </div>
                    <div className="col-md-12">
                        <TextEditor
                            editorState={editorState}
                            onEditorStateChange={setEditorState}
                        />
                    </div>
                </div>
                <div className="text-center col-md-12">
                    <button type="submit" className="mt-4 btn btn-primary">
                        Save
                    </button>
                </div>
            </form>
        </div>
    );
};

export default AboutUsForm;
